const FORMS=['perfect competition','monopolistic competition','oligopoly','monopoly'];
const FORM_Q=[['do firms have market power',[0,1,1,1],'Table 2: every form except perfect competition.'],['are there barriers to entry',[0,0,1,1],'Table 2: oligopoly and monopoly.'],['are there many producers',[1,1,0,0],'Table 2: perfect competition and monopolistic competition.'],['are firms price takers',[1,0,0,0],'Only under perfect competition (horizontal demand at the market price).'],['is there strategic interaction between firms',[0,0,1,0],'Only under oligopoly: few firms take each other’s reactions into account.'],['is there free entry and exit',[1,1,0,0],'Perfect competition and monopolistic competition.'],['can products be differentiated',[0,1,1,0],'Monopolistic competition (differentiated) and oligopoly (homogeneous or differentiated); a monopoly sells a unique product.'],['does a firm face a downward-sloping demand curve',[0,1,1,1],'All price setters: monopolistic competition, oligopoly, monopoly.'],['is the long-run economic profit driven to zero by entry',[1,1,0,0],'Free entry: perfect competition and monopolistic competition.']];
const G_FORMS={kind:'gen',id:'g-c1-forms',topic:'c1',title:'“In how many of the four market forms…?”',blurb:'The midterm’s counting MCQ, from Table 2',
 gen:u=>{const k=u.int(0,FORM_Q.length-1);return {k}},
 q:v=>`<p>In how many of the four market forms ${FORM_Q[v.k][0]}?</p>`,
 parts:[{label:'Number of market forms',type:'choice',o:['0','1','2','3','4'],a:v=>FORM_Q[v.k][1].reduce((a,b)=>a+b,0)},{label:'Which ones?',type:'choice',o:v=>{const r=FORM_Q[v.k][1];return [FORMS.filter((_,i)=>r[i]).join(', ')||'none','all four',FORMS.filter((_,i)=>!r[i]).join(', ')||'none']},a:0}],
 steps:v=>[`${FORM_Q[v.k][2]}`,T(['Market form','Answer'],FORMS.map((f,i)=>[f,FORM_Q[v.k][1][i]?'yes':'no']))]};
const G_PCTQ={kind:'gen',id:'g-c1-pctq',topic:'c1',title:'Use an elasticity: predicted change in quantity',blurb:'%Δq = ε × %Δp, then name the demand',levels:['Price rise','Price cut'],
 gen:(u,lv)=>{const e=u.pick([0.1,0.2,0.4,0.5,0.8,1,1.2,1.5,2,2.5,3]),dp=u.pick([2,4,5,10,20])*(lv?-1:1);return {e:-e,dp,dq:U.round(-e*dp,6)}},
 q:v=>`<p>The price elasticity of demand is ε = ${fmt(v.e)}. The price ${v.dp>0?'rises':'falls'} by ${Math.abs(v.dp)}%. By how many percent does the quantity demanded change (approximately)?</p>`,
 parts:[{label:'%Δq',answer:v=>v.dq,unit:'%',tol:0.01},{label:'Demand is',type:'choice',o:['perfectly inelastic','inelastic','unitary elastic','elastic','perfectly elastic'],a:v=>Math.abs(v.e)<1?1:Math.abs(v.e)===1?2:3},{label:'Its curve (p on the vertical axis) is',type:'choice',o:['vertical','steep','flat','horizontal'],a:v=>Math.abs(v.e)<1?1:2}],
 steps:v=>[`ε ≈ %Δq / %Δp, so %Δq ≈ ε × %Δp = ${fmt(v.e)} × ${v.dp>0?'':'('}${fmt(v.dp)}${v.dp>0?'':')'}% = <b>${fmt(v.dq)}%</b>.`,`|ε| = ${fmt(Math.abs(v.e))} ${Math.abs(v.e)<1?'&lt; 1: inelastic (steep curve): quantity reacts less than proportionally.':Math.abs(v.e)===1?'= 1: unitary elastic.':'&gt; 1: elastic (flat curve): quantity reacts more than proportionally.'}`]};

/* ---- chapter 1: notions added from the midterm site ---- */
const C1_FIRM=NOTION({id:'c1-firm',title:'0. Firm decision-making (slides)',
 ess:'<p>The firm is “a production unit that transforms inputs into output and creates with this process added value”. Of the three economically meaningful objectives (cost minimization, revenue maximization, <b>profit maximization</b>), the course uses profit maximization. <b>Economic profit</b> (market values, opportunity costs) is more useful for decisions than accounting profit.</p>',
 understand:`<p>${MIDP} Slides only, so lighter weight: know the definitions.</p><ul>
 <li><b>The firm</b>: “a production unit that transforms inputs into output and creates with this process added value”. Inputs: labour, capital, materials. Given technological and market constraints.</li>
 <li><b>Three economically meaningful objectives</b>: cost minimization (minimize costs for a given output), revenue maximization (maximize revenues given the input), <b>profit maximization</b>. Size, quality or status maximization are less meaningful in the long term. The objective concerns the <i>principal</i>, not the agent.</li>
 <li><b>Accounting vs economic profit</b>: accounting profit uses historical costs and serves legal and reporting needs. Economic profit uses market values and includes <b>opportunity (implicit) costs</b>; it is the more useful measure for managerial decisions.</li>
 <li><b>Sources of profit</b>: innovation, risk taking, exploiting market inefficiencies (barriers to entry, sophisticated pricing, diversifying, good production decisions).</li>
 <li><b>CSR</b>: economic profit should include social and ecological costs and revenues; CSR can be seen as a managerial tool to ensure long-term economic profits.</li></ul>
 <p>Consumers are assumed <b>rational</b>: they maximize utility under their budget constraint and re-optimize when prices change (notion 1).</p>`,
 trap:'Accounting profit ≠ economic profit: economic profit subtracts the opportunity cost of the owner’s resources, so a firm can show an accounting profit and a zero economic profit.',
 tryit:{q:'Which measure includes opportunity (implicit) costs?',o:['Economic profit','Accounting profit','Revenue'],a:0,e:'Economic profit uses market values and opportunity costs; accounting profit uses historical costs.'}});
const C1_BIGTECH=NOTION({id:'c1-bigtech',title:'10. Societal discussion: market power and Big Tech',
 ess:'<p>The INSIGHTS conclude that policy action against anti-competitive conduct by Big Tech is warranted. The slides use discussion cases: AB InBev / SABMiller, insulin pricing, taxing sugary drinks, “Is Meta a monopolist?”, the alcohol-free Virgin Mary pub, superstar firms and the labour share.</p>',
 understand:`<p>${MIDP} Know the gist of each case and the concept it illustrates:</p><ul>
 <li><b>AB InBev / SABMiller</b> (case M.7881): one in three beers worldwide under one firm. Concerns: competition, dominance, consumer choice → risk of higher prices. Market considered: beer, national. The EC approved it <b>under conditions</b> (e.g. Peroni sold to Asahi). Whether it was good or bad remains open.</li>
 <li><b>Insulin pricing</b>: demand is very inelastic; with limited competition, is price regulation warranted? (price elasticity, market power)</li>
 <li><b>Taxing sugary drinks</b>: links to price elasticity.</li>
 <li><b>Is Meta a monopolist? Should it be broken up?</b> Links to network externalities.</li>
 <li><b>Virgin Mary, an alcohol-free pub in Dublin</b>: product differentiation, creating a niche under monopolistic competition.</li>
 <li><b>Superstar firms and the labour share</b> (Autor): rising market power and a falling labour share.</li></ul>`,
 trap:'The discussion cases illustrate the concepts; the exam assesses the INSIGHTS. Link each case to its concept (elasticity, network externalities, differentiation, excessive market power).',
 tryit:{q:'“Is Meta a monopolist?” mainly illustrates which barrier to entry?',o:['Network externalities','Exclusive usage rights','Economies of scale only'],a:0,e:'The value of a platform grows with its users: winner-takes-all.'}});
const C1_SORT=EXI({id:'w-c1-sortmarkets',type:'sort',title:'Classify real markets (exercise 1.7 and the course’s examples)',q:'Put each real market in its market form. A card wrongly placed shows the reason.',cats:['(Close to) perfect competition','Monopolistic competition','Oligopoly','Monopoly'],pick:10,
 items:[['Wooden HB pencils','(Close to) perfect competition','many producers, largely homogeneous, each small (Ex. 1.7)'],['Copper','(Close to) perfect competition','homogeneous commodity, price takers (Ex. 1.7)'],['Some agricultural sectors','(Close to) perfect competition','Table 2'],['Bottled water','Monopolistic competition','many firms, branding and advertising (Ex. 1.7)'],['Strawberry jam','Monopolistic competition','many brands, differentiated, easy entry (Ex. 1.7)'],['Lipstick','Monopolistic competition','many brands, differentiated, easy entry (Ex. 1.7)'],['Economics textbooks','Monopolistic competition','many publishers and authors, differentiated (Ex. 1.7)'],['Restaurants in a large city','Monopolistic competition','differentiated cuisine, location, quality, atmosphere (Ex. 1.7)'],['Retail trade','Monopolistic competition','Table 2'],['An alcohol-free pub in Dublin (Virgin Mary)','Monopolistic competition','a niche created by product differentiation (slides)'],['Mobile phone producers','Oligopoly','few large firms; technological, scale, branding and legal barriers (Ex. 1.7)'],['Mobile phone operators','Oligopoly','spectrum, infrastructure, regulation and scale barriers (Ex. 1.7)'],['Oil, steel','Oligopoly','Table 2'],['Smartphones','Oligopoly','market atomism violated'],['Retail water and sewerage in a region','Monopoly','within a region; sometimes oligopoly-like depending on institutions (Ex. 1.7)'],['Public utilities','Monopoly','Table 2']]});

/* ---- chapter 2: Varian's credibility trees and the centipede figure ---- */
const VARIAN=[['Game 1',[[[5,9],[5,5]],[[7,6],[5,4]]],'Player 2’s claim to choose c after a is credible (9 &gt; 5). Her claim to choose e after b is also credible (6 &gt; 4). So player 1 compares 5 (via a) with 7 (via b) and chooses <b>b</b>.'],
 ['Game 2: change c to (5 ; 3)',[[[5,3],[5,5]],[[7,6],[5,4]]],'A claim by player 2 to choose c after a is no longer credible: after a she does best with d (5 &gt; 3). Player 1 still chooses <b>b</b> (7 &gt; 5).'],
 ['Game 3: can player 1 get 15?',[[[5,9],[15,5]],[[7,3],[5,12]]],'After a, player 2 chooses c (9 &gt; 5), so player 1 gets 5, not 15. After b, player 2 chooses f (12 &gt; 3): again 5. Player 1 cannot reach 15.'],
 ['Game 4: give 5 points away',[[[5,9],[10,10]],[[7,3],[5,12]]],'If player 1 changes payoffs so that d gives (10 ; 10), player 2’s commitment to d after a becomes credible (10 &gt; 9). Player 1 chooses <b>a</b> and gets 10 instead of 5. Subgame-perfect: every action chosen is rational for the player who chooses it.']];
const VARIAN_STEPS=VARIAN.map(([t,pay,note],k)=>({kind:'steps',id:'st-c2-varian'+(k+1),topic:'c2',title:`Credibility (Varian): ${t}`,blurb:'What does player 1 choose, and why? Decide, then reveal.',
 intro:`<p>Player 1 chooses a or b; player 2 then chooses c or d after a, e or f after b. Payoffs (player 1 ; player 2). ${MIDP}</p>${seqTree(pay,{a:['a','b'],b:[['c','d'],['e','f']]})}`,
 steps:[`After a, player 2 compares c (${pay[0][0][1]}) and d (${pay[0][1][1]}).`,`After b, player 2 compares e (${pay[1][0][1]}) and f (${pay[1][1][1]}).`,note,seqTree(pay,{a:['a','b'],b:[['c','d'],['e','f']],solve:true,cap:'Ch 2 slides (from Varian, 2010). Thick: subgame-perfect choices.'})]}));
const CENT_FIG=(()=>{const who=['A','B','A','B','A','B'],stop=[[2,0],[1,3],[4,2],[3,5],[6,4],[5,7]],x=k=>30+k*52;let g='';
 for(let k=0;k<6;k++){g+=`<line x1="${x(k)}" y1="40" x2="${k===5?x(6)-14:x(k+1)}" y2="40" style="stroke:var(--ink);stroke-width:1.5"/><line x1="${x(k)}" y1="40" x2="${x(k)}" y2="88" style="stroke:var(--ink);stroke-width:1.5"/>`;
  g+=`<circle cx="${x(k)}" cy="40" r="11" style="fill:var(${who[k]==='A'?'--debit':'--surface'});stroke:var(--debit);stroke-width:2"/><text x="${x(k)}" y="44" text-anchor="middle" class="pp" style="${who[k]==='A'?'fill:var(--surface)':''}">${who[k]}</text><text x="${x(k)}" y="104" text-anchor="middle" class="pm">(${stop[k].join(';')})</text>`}
 g+=`<text x="${x(6)}" y="44" text-anchor="middle" class="pm">(8;6)</text><text x="${x(0)+14}" y="18" class="pt">Continue →   (down = Stop)</text>`;
 return `<figure class="fig"><svg class="plot" viewBox="0 0 360 115" role="img" aria-label="Six-stage centipede game">${g}</svg><figcaption>INSIGHTS Ch 2, Figure 1: players alternate; Stop ends the game at the payoff below the node; payoffs (A ; B).</figcaption></figure>`})();

const HOTEL_PLOT=Object.assign({kind:'plot',id:'p-c2-hotel',topic:'c2',title:'Hotelling’s beach',blurb:'Place the two carts; under fixed prices, who gains by moving?',
 params:[{k:'x1',label:'Cart 1 position (km)',min:0,max:2,step:0.05,v:0.5,fmt:x=>fmt(U.round(x,2))+' km'},{k:'x2',label:'Cart 2 position (km)',min:0,max:2,step:0.05,v:1.5,fmt:x=>fmt(U.round(x,2))+' km'}],
 x:{max:2,label:'beach (km)'},y:{max:1,label:' '},
 draw:p=>{const h=hotel(p.x1,p.x2),L=p.x1<=p.x2;return {areas:[{pts:[[0,0],[0,0.5],[h.b,0.5],[h.b,0]],c:L?'--debit':'--credit',l:Math.round(h.shareL*100)+'%'},{pts:[[h.b,0],[h.b,0.5],[2,0.5],[2,0]],c:L?'--credit':'--debit',l:Math.round(h.shareR*100)+'%'}],
  points:[{x:p.x1,y:0.7,l:'cart 1',c:'--debit'},{x:p.x2,y:0.85,l:'cart 2',c:'--credit'}],vx:[{x:h.b,c:'--muted',dash:true}]}},
 readout:p=>{const h=hotel(p.x1,p.x2),s1=p.x1<=p.x2?h.shareL:h.shareR,center=Math.abs(p.x1-1)<0.01&&Math.abs(p.x2-1)<0.01;
  return RT([['Market share cart 1',Math.round((p.x1===p.x2?0.5:s1)*100)+'%'],['Market share cart 2',Math.round((p.x1===p.x2?0.5:1-s1)*100)+'%'],['Average walk to the nearest cart',Math.round(h.avg*1000)+' m'],['Socially optimal (0.5 and 1.5 km)','250 m']])
   +`<p class="hint">${center?'Both at the centre: no cart gains by moving (fixed prices) → the Nash equilibrium, a homogeneous duopoly. With free prices this becomes Bertrand’s price war, so they would move apart.':'Under fixed prices, the cart further from the centre gains customers by moving towards the other one. Keep moving them: where does it stop?'} ${OUT} shares and walking distances are computed by the site.</p>`}},{presets:HOTEL_PRESETS});

const MODEL_C2={"vocab":"<div class=\"grid2\">\n<div class=\"def\"><b class=\"term\">Game</b><p>A situation where the decision-makers take into account interdependence.</p></div>\n<div class=\"def\"><b class=\"term\">Players</b><p>The (rational) decision-makers.</p></div>\n<div class=\"def\"><b class=\"term\">Pure strategies</b><p>The possible actions of the players. In this course choices are <b>discrete</b>: only a limited number of output levels can be chosen.</p></div>\n<div class=\"def\"><b class=\"term\">Payoff matrix</b><p>The outcomes for each player for each possible combination of strategies. Convention: <b>(player 1 ; player 2)</b>, player 1 in rows.</p></div>\n</div>\n<div class=\"key\"><span class=\"eyebrow\">Assumptions about players</span>\n<ul style=\"margin:0;padding-left:1.2em\"><li><b>Individualistic</b>: driven by self-interest, striving for the best outcome for themselves (profit, sales).</li><li><b>Rational</b>, and each understands the rules of the game.</li><li>They play a <b>one-shot simultaneous game</b>: once, at the same moment.</li></ul></div>\n<div class=\"prose\">\n<p><b>Cartel agreement</b> (course definition): firms agree to cooperate and coordinate on quantity and/or price to maximize the <b>sum</b> of their profits, as if they were one merged monopolist. In the duopoly game: <b>maintain</b> the cartel = <b>low</b> output (keeps the price high); <b>break</b> the cartel = <b>high</b> output.</p>\n<p>The slides add two managerial perspectives: <b>game theory</b> = how to <i>play</i> the game (which strategy maximizes profit given the strategic interaction); <b>mechanism design</b> = how to <i>design</i> the game (which market conditions to install, e.g. auctions).</p>\n</div>","pd":"<div class=\"prose\"><p>Two suspects, interrogated separately, cannot confer. Payoffs are <b>years in prison</b>, so <b>lower is better</b>.</p></div>\n@@MX:pd@@\n<div class=\"def\"><b class=\"term\">Dominant strategy</b><p>A strategy that always produces the best result for that player, <b>regardless of what the other player does</b>. If a player has a dominant strategy, all their other strategies are <b>dominated</b>.</p></div>\n<div class=\"prose\">\n<p>Prisoner 1: if prisoner 2 confesses, confess (8 &lt; 10 years); if prisoner 2 denies, confess (1 &lt; 2 years). Confess is dominant, and the same holds for prisoner 2. Rational prisoner 2 also expects prisoner 1 to confess and can \"delete\" the dominated row; the order in which dominated strategies are deleted does not matter.</p>\n<p>Expected solution: <b>(s1, t1) = (confess, confess)</b>, 8 years each, while (deny, deny) would give 2 years each.</p>\n</div>\n<div class=\"key\"><span class=\"eyebrow\">Central insight of game theory</span><p>The blind pursuit of self-interest does not necessarily lead to the best outcome for the individual himself.</p></div>","dom":"@@MX:t2@@\n<div class=\"def\"><b class=\"term\">Equilibrium in dominant strategies</b><p>Each player plays his/her dominant strategy; the expected outcome consists of two dominant strategies. Rational players always play a dominant strategy and anticipate that others play theirs.</p></div>\n<div class=\"prose\"><p>Table 2: break is best for duopolist 1 whether 2 maintains (4500 &gt; 4000) or breaks (3000 &gt; 2900); symmetric for duopolist 2. <b>(Break, Break)</b> is an equilibrium in dominant strategies, although (Maintain, Maintain) gives both more and maximizes the sum of profits.</p></div>","nash":"<div class=\"def\"><b class=\"term\">Nash equilibrium</b><p>A combination of strategies where <b>no player wishes to change his strategy given the expected strategy of the other players</b>.</p></div>\n<div class=\"key\"><span class=\"eyebrow\">Method (slides)</span><p>For each strategy of the other player, identify the <b>best response</b>. If both players' best responses coincide in the same cell, that cell is a Nash equilibrium. In practice: underline player 1's best payoff in each <b>column</b> and player 2's best payoff in each <b>row</b>; a cell with both underlined is a Nash equilibrium.</p></div>\n<div class=\"grid2\">\n<div class=\"card\"><h4>Relationship</h4><ul style=\"margin:0;padding-left:1.2em\"><li>Every equilibrium in dominant strategies is a Nash equilibrium; not every Nash equilibrium is one in dominant strategies.</li><li>If there is an equilibrium in dominant strategies, it is also the <b>unique</b> Nash equilibrium.</li><li>The Nash equilibrium is the more general concept.</li></ul></div>\n<div class=\"card\"><h4>Expected solution</h4><ul style=\"margin:0;padding-left:1.2em\"><li>Nash equilibria need not be unique.</li><li>A <b>unique</b> Nash equilibrium is the expected solution.</li><li>If there is <b>no unique</b> Nash equilibrium, there is no expected solution in the absence of coordination.</li></ul></div>\n</div>\n<p class=\"prose\">Table 3: no dominant strategies. If 2 maintains, 1 maintains (4000 &gt; 3900); if 2 breaks, 1 breaks (3000 &gt; 2900). Two Nash equilibria: (Maintain, Maintain) and (Break, Break), so no expected solution.</p>\n@@MX:t3@@\n<p class=\"prose\">Table 4: four output levels each. Exactly <b>3 Nash equilibria</b>: (s3, t2), (s2, t3), (s3, t3). Try it in the lab: click \"Show best responses\".</p>\n@@MX:t4@@\n<div class=\"row\"><a class=\"btn\" href=\"#lab\">Open the payoff matrix lab</a></div>","coop":"<div class=\"prose\"><p>The prisoner's-dilemma insight applies to cartels, OPEC output limits, free-riding in group projects and CO₂ agreements (Kyoto, Paris).</p></div>\n<h4 class=\"wb-h3\">Battle of the sexes: two Nash equilibria</h4>\n@@MX:bos@@\n<div class=\"prose\"><p>No dominant strategy for either player. Two Nash equilibria: (Football, Football) and (Cinema, Cinema). It illustrates: (1) the importance of <b>coordinated strategies</b>, (2) <b>simultaneous vs sequential</b> choice, (3) a Nash equilibrium does not have to be <b>unique</b>.</p></div>\n<div class=\"grid2\">\n<div><h4 style=\"margin-bottom:8px\">CO₂ scenario 1 (Table 6)</h4>@@MX:co2a@@<p class=\"dgcap\" style=\"margin-top:6px\">Two NE: (reduce, reduce) and (not reduce, not reduce). Neither is the expected solution.</p></div>\n<div><h4 style=\"margin-bottom:8px\">CO₂ scenario 2 (Table 7)</h4>@@MX:co2b@@<p class=\"dgcap\" style=\"margin-top:6px\">A prisoner's dilemma: unique NE (not reduce, not reduce).</p></div>\n</div>\n<div class=\"key\"><span class=\"eyebrow\">Scenario 1: three avenues to reach the superior NE without enforceable agreements</span>\n<ol style=\"margin:0;padding-left:1.2em\"><li><b>Make the game sequential</b>: it is easier to coordinate, and there is a <b>first-mover advantage</b> (the EU moving first with the Green Deal can pull the US and Asia along).</li><li><b>Cooperation</b>: a bilateral (multilateral) agreement. Even non-enforceable, it leads to the desirable NE here, because it is an equilibrium.</li><li><b>Social norms</b> (e.g. \"never break an agreement\"), which impose the cooperative outcome from outside, like a binding agreement.</li></ol></div>\n<div class=\"key\"><span class=\"eyebrow\">Scenario 2: \"If you can't win the game, change the rules\"</span><p>When the desired outcome is not an equilibrium, non-binding agreements end in false promises. The way out is <b>mechanism design</b>: change the structure and payoffs of the game. Make unilateral defection costly (CO₂ taxes, consumer action, social awareness), e.g. lower the defection payoff from 10 to 3. That turns Table 7 into Table 6, where (reduce, reduce) is a possible NE reachable by agreements or sequential choice. Police interrogate suspects separately and simultaneously on purpose: that design makes (confess, confess) the expected solution.</p></div>\n<p class=\"src\">The course discusses non-cooperative game theory: binding agreements are assumed impossible. Cooperative game theory assumes agreements are implemented.</p>","bigtech":"<h4 class=\"wb-h3\">Maintain–break game and antitrust</h4>\n@@MX:mb@@\n<div class=\"prose\"><p>Breaking is dominant for both; <b>(Break, Break)</b> is the unique NE although both prefer (Maintain, Maintain). EU competition law (Article 101 TFEU) prohibits cartels: price fixing, restricting output, dividing markets. But prohibiting explicit agreements does not necessarily produce the competitive outcome, because firms interact repeatedly.</p></div>\n<h4 class=\"wb-h3\">Repeated games: firms are there to stay</h4>\n<div class=\"def\"><b class=\"term\">Repeated game</b><p>The same players face the same or a closely related strategic situation more than once.</p></div>\n<div class=\"prose\">\n<ul>\n<li>Breaking gives an immediate gain (9000 &gt; 8000), but the rival may retaliate, leaving 2000 per period instead of 8000.</li>\n<li><b>Known final period</b>: in the last period both break (no future retaliation possible); reasoning backwards, cooperation <b>unravels</b> in earlier periods too.</li>\n<li><b>No known final period</b> (indefinitely repeated): current behaviour affects a long stream of future payoffs.</li>\n</ul>\n</div>\n<div class=\"def\"><b class=\"term\">Tit-for-tat</b><p>Begin by <b>maintaining</b>; maintain if the rival maintained in the preceding period; break if the rival broke in the preceding period. It rewards cooperation and responds to deviation. When future profits matter enough, (Maintain, Maintain) is sustainable even though (Break, Break) is the unique NE of the one-shot game. This depends on the payoffs, the observability of behaviour, and how much firms value future profits.</p></div>\n<div class=\"note\">Slides: tit-for-tat escapes an inferior NE only if the game is repeated many (indefinitely many) times. Antitrust law may be ineffective when Big Tech firms play indefinitely, because repeated interaction enables <b>tacit collusion</b> sustained by reputation and retaliation, without any communication.</div>"};
/* ---------- v3 (workbook format): chapter 2, points 1–6, in the format of the midterm revision site (MSP Revision.html, chapter 2).
   MODEL_C2 = the model's sections 2.1, 2.1.1, 2.1.2, 2.1.3, 2.2 and 2.3 (up to repeated games), text unchanged; its matrices (@@MX:game@@)
   become interactive MATRIX blocks in the text. After the model's blocks: the content of the course sheet that the model does not have,
   in the same blocks (definition cards, key boxes, traps), then the labs and "Your turn". ---------- */
const MXC=k=>MATRIX(Object.assign({id:'mx-c2-'+k,compact:true},MID_GAMES[k]));
const WBM=k=>MODEL_C2[k].replace(/@@MX:(\w+)@@/g,(m,g)=>MXC(g)).replace('href="#lab"','href="#market-structures-tools-gm-c2-lab"');
const WB=h=>`<div class="wb">${h}</div>`;
const DEF=(t,d)=>`<div class="def"><b class="term">${t}</b><p>${d}</p></div>`;
const KEY=(e,h)=>`<div class="key"><span class="eyebrow">${e}</span>${h}</div>`;
const WTRAP=(e,h)=>`<div class="trap"><span class="eyebrow">${e}</span><p>${h}</p></div>`;
const CARD=(t,h)=>`<div class="card"><h4>${t}</h4>${h}</div>`;
const SEC=(n,t)=>`<span class="secnum">${n}</span>${t}`;
const MB_PLAY=PLAY({id:'pl-c2-mb',title:'Play the maintain-break game (Table 8) against the computer',rows:['Maintain','Break'],m:[[[8000,8000],[1000,9000]],[[9000,1000],[2000,2000]]],rounds:[1,5,10,'?'],delta:0.8,strategies:['tft','allc','alld','random'],
 notes:o=>o.rounds==='?'?'Unknown end: against tit-for-tat, breaking once gains 9000 − 8000 = 1000 today but costs 8000 − 2000 = 6000 in each later round of retaliation. That is how repetition can sustain cooperation.':o.rounds===1?'One-shot game: Break is dominant, whatever the computer does.':'Known final period: in the last round no retaliation is possible, so breaking pays; reasoning backwards, cooperation can unravel (INSIGHTS 2.3.2).'});
const C2_WB=
NOTION({id:'c2-vocab',title:SEC('2.1','Game theory: the vocabulary'),
 extra:WB(WBM('vocab')+KEY('Also in the course sheet',`<p>Why game theory for oligopoly? What is optimal for duopolist 1 depends on what duopolist 2 does, and vice versa. An <b>equilibrium</b> is reached when each player chooses the best possible strategy given the strategy of the others.</p><p>In the course’s duopoly, <b>maintain</b> = low output (<b>400</b>), <b>break</b> = high output (<b>600</b>).</p><p>The course studies <b>non-cooperative</b> game theory: binding agreements are not possible (cooperative game theory assumes they are enforced by habits, law or punishment).</p>`)
  +WTRAP('Trap','In a payoff matrix (a ; b), the <b>first</b> number is always the payoff of the <b>row</b> player (player 1).')),
 tryit:{q:'In the course’s duopoly game, what does “maintain the cartel agreement” mean?',o:['Producing the high output level (600)','Producing the low output level (400) to keep the price high','Lowering the price below the rival’s'],a:1,e:'Maintaining = restricting output (400) as a merged monopoly would; breaking = producing more (600).'}})+
NOTION({id:'c2-pd',title:SEC('2.1.1','The prisoner’s dilemma'),
 extra:WB(WBM('pd')+WTRAP('Trap','Here the payoffs are <b>years in prison</b>: lower is better. Read the direction of the payoffs before marking best responses.')
  +CARD('Play it against the computer',`<p class="dgcap">One-shot, repeated (5 or 10 rounds) or unknown end; the computer’s strategy is yours to choose. Same table, payoffs (you ; computer).</p>${PLAY(PD_PLAY)}`)),
 tryit:{q:'In the prisoner’s dilemma, what is the expected solution?',o:['(Deny ; Deny): 2 years each','(Confess ; Confess): 8 years each','No expected solution: two Nash equilibria'],a:1,e:'Both have a dominant strategy (Confess), so (s1 ; t1) is the equilibrium in dominant strategies and the expected solution.'}})+
NOTION({id:'c2-dom',title:SEC('2.1.2','Equilibrium in dominant strategies'),
 extra:WB(WBM('dom')+`<div class="grid2">${DEF('Dominant strategy (mock exam answer key)','The strategy that delivers the best result for a player, irrespective of the decisions of the other player. All other strategies are then dominated.')}${DEF('Equilibrium in dominant strategies (mock exam answer key)','An expected solution consisting of dominant strategies (each player plays its dominant strategy).')}</div>`
  +KEY('Method','<p>To test whether a strategy is dominant, compare it with every other strategy of the <b>same</b> player, <b>column by column</b> (for the row player) or <b>row by row</b> (for the column player). It must be better in every case.</p>')
  +WTRAP('Trap','A player can have a dominant strategy while the other has none (mock exam Q2: duopolist 2 has one, duopolist 1 not). Then there is <b>no</b> equilibrium in dominant strategies, but there can still be a unique Nash equilibrium.')),
 tryit:{q:'Duopolist 1’s payoffs: (Maintain) 4000 vs 2900, (Break) 3900 vs 3000 (Table 3). Is Break dominant for duopolist 1?',o:['Yes','No: if the rival maintains, Maintain (4000) beats Break (3900)'],a:1,e:'Break is better only if the rival breaks (3000 &gt; 2900). Not better in every case, so not dominant.'}})+
NOTION({id:'c2-nash',title:SEC('2.1.3','Nash equilibria'),
 extra:WB(WBM('nash')+KEY('Also in the course sheet','<p>The Nash equilibrium is “a state with no tendency to deviate”. The cartel agreement (Maintain ; Maintain) is not one when each player gains by breaking it unilaterally.</p><p><b>Ties</b> (Table 4): when the rival plays t1, both s3 and s4 give 6000: both are best responses.</p>')
  +KEY('Mock exam Q2 (answer key)','<p>a) Dominant strategy: definition; duopolist 1 has none, duopolist 2 has “strategy 1”. b) Equilibrium in dominant strategies: definition; none. c) Nash equilibrium: definition; (Strategy 2 ; Strategy 1) with profits (6 ; 3). It is unique, so <b>yes, it is the expected solution</b>. d) Played sequentially with duopolist 1 as leader: the game tree gives (Strategy 2 ; Strategy 1) as SPNE.</p>')
  +WTRAP('Trap','“Is there an expected solution?” is answered with the <b>number</b> of Nash equilibria: one → yes (it is the expected solution); several → no, unless players coordinate. It is not about which outcome is best.')
  +CARD('Your own matrix, or a new one','<p class="dgcap">Generate a 2 × 2, 3 × 3 or 4 × 4 game or type your own payoffs (“Edit the payoffs”), then click the Nash equilibria and check, show the best responses, answer the exam questions (dominant strategies, equilibrium in dominant strategies, expected solution) and solve the sequential version.</p>'+MATRIX(LAB_GAME))
  +CARD('Answer like the exam',GEN(G_EXAM))),
 tryit:{q:'A 2 × 2 game has two Nash equilibria and no dominant strategies. Is there an expected solution?',o:['Yes, the one with the highest total payoff','No, not in the absence of coordination','Yes, both'],a:1,e:'Several Nash equilibria → no expected solution without coordination (battle of the sexes, Table 3).'}})+
NOTION({id:'c2-bos',title:SEC('2.2','Cooperation, social norms and contracts (climate)'),
 extra:WB(WBM('coop')+KEY('INSIGHTS wording','<p>When the desired outcome is not an equilibrium, non-binding agreements end in “false promises and disillusionment”.</p>')+WTRAP('Trap','Scenario 1 has <b>two</b> NE (no expected solution); scenario 2 has <b>one</b> (Not reduce ; Not reduce), which is a dominant-strategy equilibrium. Check the payoff of unilateral defection (3 or 10).')),
 tryit:{q:'In CO₂ scenario 2, what does mechanism design try to do?',o:['Make (Not reduce ; Not reduce) more attractive','Lower the payoff of unilateral defection so that (Reduce ; Reduce) becomes a Nash equilibrium','Force countries to play simultaneously'],a:1,e:'Change the payoffs (taxes, consumer action): defection pays 3 instead of 10, and scenario 1 returns.'}})+
NOTION({id:'c2-repeat',title:SEC('2.3','The game of Big Tech: beyond one-shot simultaneous games'),
 extra:WB(WBM('bigtech')+KEY('Conclusion of the INSIGHTS','<p>“The outcome of a game can change when present behavior affects future reactions”, which <b>complicates antitrust</b>: prohibiting explicit cartels does not guarantee the competitive outcome.</p>')
  +WTRAP('Trap','Known final period → break in the last period → cooperation unravels backwards. Indefinite horizon → tit-for-tat can sustain cooperation. Do not swap the two.')
  +CARD('Play the maintain-break game',`<p class="dgcap">${OUT} the game lets you test the course’s strategies (tit-for-tat, always maintain, always break) and a random player; the “unknown end” option continues with an 80% chance after each round.</p>${MB_PLAY}`)),
 tryit:{q:'Two firms know they will interact exactly 10 times. What does the INSIGHTS’ reasoning predict for round 10?',o:['Both maintain, to reward past cooperation','Both break: no retaliation is possible after the final period','Tit-for-tat continues'],a:1,e:'No future retaliation after the last round, so breaking is optimal there; working backwards, the same logic unravels cooperation earlier.'}});

const SHEETS={};
SHEETS.c1=`
<div class="eyebrow">Midterm · Chapter 1 (also in the final)</div><h2>Market structures and market power</h2>
<p class="lede">Goal: compute and interpret price elasticity, give the four conditions of perfect competition, characterize the four market forms, name the four barriers to entry, and link market power, markups and elasticity.</p>
${YT}
${C1_FIRM}
${NOTION({id:'c1-consumer',title:'1. Rational consumers and the demand function',
 ess:`<p>Economics starts from <b>rational consumers</b>: each one <b>maximizes utility under a budget constraint</b>. A price change moves the budget constraint, consumers re-optimize, and usually buy <b>less</b> of the good whose price rose. The <b>demand function</b> links the price p and the quantity q over many consumers with different preferences.</p>`,
 understand:`<p>The INSIGHTS call rational consumers “cold-hearted robots that pursue their self-interest, but face constraints”. Real people show altruism and other deviations; rationality is only the <b>starting point</b> that gives structural insights.</p><ul><li>Self-interest = buy what is best in pleasure, well-being, comfort: <b>utility</b>.</li><li>Constraint = the <b>budget</b>: the bundle must be affordable.</li><li>Chosen bundle = the best affordable one.</li><li>Demand of a market = a representative consumer, or the sum of many consumers (Kilian prefers football, Angèle music).</li></ul>`,
 tryit:{q:'The price of salads rises. What does the course expect a rational consumer to do?',o:['Keep the same bundle: preferences did not change','Re-optimize under the new budget constraint, usually buying fewer salads','Buy more salads, since they signal quality'],a:1,e:'A price change modifies the budget constraint; the consumer re-optimizes and usually consumes less of the dearer product.'}})}
${NOTION({id:'c1-elast',title:'2. Price elasticity of demand',
 ess:`${F('Price elasticity  ε = %Δq / %Δp ≈ (Δq / q) / (Δp / p)      (usually negative)')}<p><b>Elastic</b>: |ε| &gt; 1 (demand reacts more than proportionally). <b>Inelastic</b>: |ε| &lt; 1. Perfectly elastic |ε| = ∞, perfectly inelastic |ε| = 0, unitary |ε| = 1.</p>`,
 extra:`<div class="grid2">${FIG({xmax:10,ymax:10,xl:'q',yl:'p',curves:[{f:()=>5,c:'--debit',l:'|ε| = ∞'}]},'Perfectly elastic: horizontal (Stromae)')}${FIG({xmax:10,ymax:10,xl:'q',yl:'p',lines:[{x1:5,y1:0,x2:5,y2:10,c:'--credit',l:'|ε| = 0'}]},'Perfectly inelastic: vertical (Indila)')}${FIG({xmax:10,ymax:10,xl:'q',yl:'p',curves:[{f:x=>8-0.6*x,c:'--debit',l:'flat: elastic'}]},'Flat demand: a small price change moves q a lot')}${FIG({xmax:10,ymax:10,xl:'q',yl:'p',curves:[{f:x=>10-2.5*x,c:'--credit',l:'steep: inelastic',to:4}]},'Steep demand: q barely reacts')}</div><p class="hint">Figure 1 of the INSIGHTS, redrawn: price elasticity relates to the slope of the inverse demand function.</p>`,
 understand:`<p>Elasticity compares <b>percentages</b>, so it does not depend on units (euros or dollars, kilos or tonnes). Read ε = −1.159 for apples as: “a 1% price increase goes with a 1.159% fall in the quantity demanded”.</p>
 ${T(['|ε|','Name','Examples in the INSIGHTS'],[['∞','perfectly elastic','Stromae: on the platform All The Same, at 2 $ per € he exchanges everything there; at 0.5 $ per € nothing'],['&gt; 1','elastic','apples (U.S.) −1.159, lettuce (U.S.) −2.58, beer and malt beverages (U.S.) −2.83, cigarettes (U.S.) −1.107, regular economy US–Europe airline travel −1.30'],['1','unitary elastic','—'],['&lt; 1','inelastic','gasoline in Canada, short run −0.01 to −0.2 (long run −0.4 to −0.8), child care (North America) −0.570, government health care (Kenya) −0.100, first-class US–Europe airline travel −0.45, home care for the disabled elderly (France) −0.4, electricity, private households (France) −0.8'],['0','perfectly inelastic','Indila in the desert buys the water even at €1 000']])}
 <p>Managerial lesson of the INSIGHTS: markets where consumers are <b>price-insensitive</b> (inelastic) give firms more potential to make profits. iPhones or pizzas? Consumers are more sensitive to pizza prices (many substitutes).</p>
 <p>${MIDP} Usually <b>negative</b> (price ↑ → quantity ↓), often reported in absolute value; the slides add that it can be positive (Giffen and Veblen goods). Price elasticity relates to the slope of the <b>inverse demand function</b> (how p depends on q). Managerial lesson: select and/or create a market with price-<b>inelastic</b> demand.</p>${GEN(G_PCTQ)}`,
 example:['Cigarettes and health care (questions of the INSIGHTS)',`<p>Cigarettes: ε = −1.107, so |ε| &gt; 1: a tax that raises the price by 10% lowers consumption by about 11%: the policy works. Gasoline in the short run (−0.01 to −0.2): a price rise hardly changes consumption, but more in the long run (−0.4 to −0.8) when people can adapt. Government health care in Kenya (−0.100): very inelastic, people keep consuming a vital service.</p>`],
 trap:'Elasticity is %Δ<b>quantity</b> divided by %Δ<b>price</b>, not the reverse; and “perfect price elasticity” means |ε| = ∞, not |ε| &lt; 1 (additional exercise 1.A2). Elasticity is about <b>relative</b> (percentage) changes, not the slope itself. “Elastic” means |ε| &gt; 1, i.e. demand reacts more than proportionally to the price. The sign is usually negative: compare absolute values.',
 tryit:{q:'The price rises by 4% and the quantity demanded falls by 6%. Price elasticity ε?',answer:-1.5,tol:0.01,e:'ε = −6% / +4% = −1.5: |ε| &gt; 1, demand is elastic.'}})}
${NOTION({id:'c1-pc',title:'3. Perfect competition: four conditions, price takers',
 ess:`<p>Perfect competition needs four conditions <b>simultaneously</b>: <b>market atomism</b>, <b>perfect information</b>, <b>homogeneity</b>, <b>free entry and exit</b>. Each firm is a <b>price taker</b>: it faces a perfectly elastic (horizontal) demand at the market price and produces where <b>p = MC</b>.</p>`,
 understand:`<ul><li><b>Market atomism</b>: individual actions (raising or cutting the price) do not affect the market price.</li>
 <li><b>Perfect information</b>: consumers know the quality and the prices of all suppliers; producers know the buyers’ willingness to pay.</li>
 <li><b>Homogeneity</b>: all firms sell a product that consumers consider identical (perfect substitutes).</li>
 <li><b>Free entry and exit</b>: anyone can start production whenever they wish, any firm can leave whenever it wishes.</li></ul>
 <p>Why p = MC? Producing beyond that point adds more cost than revenue; producing less leaves profitable units unsold (the INSIGHTS’ two bullets). Why horizontal demand? Charge more and every informed consumer buys the identical product elsewhere; charge less and you lose money for nothing, since you can sell everything at the market price.</p>
 <p>Perfect competition is rare but is the <b>reference point</b> of policymakers: under certain conditions it is best for societal welfare.</p>
 <p>${MIDP} All four market forms have <b>many buyers</b>; markets with few or one buyer (monopsony) are out of scope. In p = MC, p is also the <b>additional revenue</b> of one more unit: beyond that point extra costs exceed extra revenue; before it, extra revenue still exceeds extra cost.</p>`,
 example:['Mock exam Q1a: why are iPhones not sold under perfect competition?',`<p>Apple operates under <b>oligopoly</b> (0.5 pt). <b>Free entry/exit</b> is violated (barriers: technology, scale, brand, patents), <b>market atomism</b> is violated (Apple’s decisions move the market), and <b>homogeneity</b> is not satisfied (an iPhone is differentiated). The four conditions with their explanation: 1 pt if all correct, 0.5 if at least three.</p>`],
 trap:'The mock exam gives points only if each condition is <b>explained</b>, not just named. And all four must hold <b>at the same time</b>.',
 tryit:{q:'Which condition of perfect competition fails first for washing powder, according to the INSIGHTS?',o:['Market atomism','Homogeneity (product differentiation)','Free entry and exit','Perfect information'],a:1,e:'Washing powders differ subjectively (marketing) and objectively (composition): product differentiation.'}})}
${NOTION({id:'c1-mono',title:'4. Monopoly and the four barriers to entry',
 ess:`<p>A <b>monopolist</b> is the only supplier of a product without good substitutes: a <b>price setter</b> facing the declining market demand curve. Its profit lasts only behind <b>barriers to entry</b>: (1) technological (economies of scale, natural monopoly), (2) exclusive usage rights and legal barriers, (3) strategic behaviour of the monopolist, (4) network externalities.</p>`,
 understand:`<ol><li><b>Technological barriers</b>: increasing returns to scale over a wide range of output; one firm can serve (almost) the whole demand at the minimum average cost; a rival could only serve a small residual and would not be profitable. First-mover advantages (learning effects) reinforce it → <b>natural monopoly</b> (chapter 4).</li>
 <li><b>Exclusive usage rights and legal barriers</b>: sole owner of a scarce resource (bauxite), know-how (Coca-Cola recipe), patents. Recycling or imitation can break it, but imitation is often prohibited by law.</li>
 <li><b>Strategic behaviour</b>: expensive patent lawsuits, reputation built by costly marketing so that newcomers must also advertise heavily. Works only if the threats are <b>credible</b>.</li>
 <li><b>Network externalities</b>: a platform’s value depends on its number of users → winner-takes-all markets.</li></ol>
 <p>Market power is limited by demand: with a declining demand curve, a higher price means selling less.</p>`,
 trap:'A monopolist does not choose “any price”: it chooses a point on the demand curve. Raising the price lowers the quantity sold.',
 tryit:{q:'A firm owns the only bauxite mine of a region. Which barrier to entry?',o:['Technological barrier','Exclusive usage rights of production factors','Strategic behaviour','Network externalities'],a:1,e:'Exclusive ownership of a scarce resource (the INSIGHTS’ bauxite example).'}})}
${NOTION({id:'c1-oligo',title:'5. Oligopoly: few firms, strategic interaction',
 ess:`<p><b>Oligopoly</b>: a small number of suppliers and many buyers (smartphones). Market atomism fails, so each firm must take into account the <b>behaviour of its rivals</b> and the effect of its own behaviour on them: <b>strategic interaction</b>. Homogeneous or heterogeneous; two firms = <b>duopoly</b>. Barriers keep the number of firms small in the short and long run.</p>`,
 understand:`<p>The fundamental difference: under monopoly and perfect competition, a firm only needs <b>its own cost structure and demand curve</b> to decide its output. In an oligopoly, the quantity a firm can sell at a given price depends on the quantities of the others, and its own quantity changes the price the others get. Chapter 2 models this with game theory.</p>`,
 tryit:{q:'What distinguishes oligopoly from monopolistic competition?',o:['Oligopolists sell homogeneous products only','Oligopolists must take the reactions of rivals into account (strategic interaction)','Only monopolistic competitors have market power'],a:1,e:'Few firms → strategic interaction. Under monopolistic competition, many small firms: no strategic interaction.'}})}
${NOTION({id:'c1-moncomp',title:'6. Monopolistic competition: differentiation and free entry',
 ess:`<p>Many firms, perfect information, free entry and exit, but <b>product differentiation</b>: each firm has its <b>own downward-sloping demand</b> (finite elasticity), hence some market power. In the long run, entry erodes profit: the incumbent’s demand shifts <b>inward</b> and becomes <b>flatter</b> until profit is <b>zero</b>.</p>`,
 extra:FIG({xmax:20,ymax:20,xl:'q',yl:'p',curves:[{f:x=>18-1.2*x,c:'--debit',l:'demand before entry',lx:4},{f:x=>12-0.6*x,c:'--credit',l:'after entry: inward and flatter',lx:12}]},'Entry of similar products shifts the incumbent’s demand inward and makes it flatter (more elastic).'),
 understand:`<p>Differentiation can be <b>real or only perceived</b> (image built by advertising: blind tests of beers), <b>geographic</b> (a bank branch nearby, the convenience store that sells milk dearer), or <b>multidimensional</b> (hotel X with tennis court near the airport, hotel Y with pool in the centre).</p>
 <p>It mixes the two pure forms: like a <b>monopoly</b>, each firm has its own sub-market and a downward-sloping demand; like <b>perfect competition</b>, many small firms (a price cut by one barely affects the others, so no strategic interaction) and free entry and exit. Introduced by Chamberlin and Robinson.</p>
 <p>Managerial lesson: under monopolistic competition, keep innovating, marketing and differentiating to escape the long-run zero profit (the profitable Irish pub is soon copied).</p>
 <p>${MIDP} <b>Product differentiation</b>: different products meet the same need but are perceived differently by consumers; it does not matter whether the differences are real (objective) or only in the consumer’s eyes (subjective). <b>Advertising and image</b> create (sometimes artificial) differentiation, which <b>decreases</b> the price elasticity of demand and gives the brand more market power (beer in blind tests, some pharmaceuticals, “Italian” shoes or pasta).</p>
 <div class="key"><b>Short run</b>: the number of producers and some inputs (capital, buildings) are fixed. <b>Long run</b>: all inputs are freely chosen and firms can enter or exit.</div>`,
 trap:'The difference between monopoly and monopolistic competition is in the <b>long run</b>: free entry drives profit to zero under monopolistic competition, not under monopoly. Monopolistic competition has <b>no barriers to entry</b> (“legal constraints are a barrier to entry under monopolistic competition” is false, exercise 1.6); its firms are <b>price setters</b>, not price takers (1.A3); a strong image makes demand <b>less</b> price sensitive: |ε| decreases (1.5).',
 tryit:{q:'A profitable Irish pub opens in a city and competitors copy the concept. What happens to the demand curve of the first pub?',o:['Shifts outward and becomes steeper','Shifts inward and becomes flatter','Unchanged: its product is unique'],a:1,e:'Fewer customers at each price (inward) and more substitutes, hence more price-sensitive demand (flatter).'}})}
${NOTION({id:'c1-forms',title:'7. The four market forms at a glance',
 ess:T(['Market form','Examples','Producers','Product','Market power','Barriers to entry'],[['Perfect competition','some agricultural sectors','many','homogeneous','no','no'],['Monopolistic competition','retail trade','many','differentiated','yes','no'],['Oligopoly','oil, steel, tech','some','homogeneous or differentiated','yes','yes'],['Monopoly','public utilities','one','unique product','yes','yes']]),
 example:['Exercise 1.7: classify the markets (course solution)',T(['Market','Form','Why'],[['Wooden HB pencils','(close to) perfect competition','many producers, largely homogeneous, each small'],['Copper','(close to) perfect competition','homogeneous commodity, price takers'],['Bottled water','monopolistic competition','many firms, branding and advertising'],['Strawberry jam, lipstick','monopolistic competition','many brands, differentiated, easy entry'],['Economics textbooks','monopolistic competition','many publishers and authors, differentiated'],['Restaurants in a large city','monopolistic competition','differentiated cuisine, location, quality, atmosphere'],['Mobile phone producers','oligopoly','few large firms; technological, scale, branding and legal barriers'],['Mobile phone operators','oligopoly','spectrum, infrastructure, regulation and scale barriers'],['Retail water and sewerage','monopoly (within a region)','sometimes oligopoly-like depending on institutions'],['Breakfast cereal','open for discussion','few dominant brands (oligopoly) plus many small differentiated brands']])],
 understand:`<p>Table 2 (INSIGHTS Ch 1, based on Allen et al., 2013): learn it by heart, it answers every “In how many of the four market forms…?” question.</p>${GEN(G_FORMS)}${C1_SORT}`,
 trap:'Read the table by columns: only perfect competition has <b>no market power</b>; only the two last forms have <b>barriers to entry</b>; “differentiated” products appear in monopolistic competition and possibly oligopoly.',
 tryit:{q:'Many producers, differentiated products, no barriers to entry. Which market form?',o:['Perfect competition','Monopolistic competition','Oligopoly','Monopoly'],a:1,e:'Table 2: many producers + differentiated + market power + no barriers = monopolistic competition.'}})}
${NOTION({id:'c1-power',title:'8. Market power, markup and the Lerner index',
 ess:`${F('Markup  µ = p*(q*) / MC(q*)        market power ⇔ µ > 1\nLerner index  (p* − MC(q*)) / p* = 1 / |ε|')}<p>Market power = the ability to substantially influence the market price: the profit-maximizing price exceeds marginal cost. Elasticity and market power are <b>inversely related</b>: |ε| = ∞ → no market power (µ = 1); |ε| = 0 → extreme market power (µ = ∞).</p>`,
 understand:`<p>Intuition: if your customers barely react to price (low |ε|), you can raise the price far above marginal cost without losing many sales. If they react strongly, any price above MC sends them away. The Lerner index puts a number on it: the share of the price that is above marginal cost equals 1/|ε|.</p>
 <p>The slope of the inverse demand function therefore determines market power and the potential to make profits. Real monopoly, oligopoly and monopolistic competition have 0 &lt; |ε| &lt; ∞: some market power.</p>
 <p>De Loecker et al. (2020): markups have risen sharply in recent years, driven by a <b>small minority of firms</b> setting very high markups, in the US, Europe and Asia.</p>
 ${EX('Using the Lerner index (no calculator needed)','midterm site',`<p>|ε| = 4 and MC = 30. Lerner = 1/4 → (p − 30)/p = 0.25 → p − 30 = 0.25p → 0.75p = 30 → <b>p = 40</b>. Markup µ = 40/30 ≈ 1.33 &gt; 1, so the firm has market power.</p><p class="hint">The formula is the course’s; the numbers are a practice example of the midterm site.</p>`)}`,
 example:['Mock exam Q3e: the T-shirt seller',`<p>p* = 14 and MC(3) = 11: <b>p* &gt; MC</b>, so the seller has market power. Markup µ = 14 / 11 ≈ 1.27 &gt; 1. Lerner index (14 − 11) / 14 ≈ 0.214, which corresponds to |ε| ≈ 4.67 at the optimum.</p>`],
 trap:'µ is a ratio p/MC (≥ 1), the Lerner index a share (p − MC)/p between 0 and 1. Do not mix them up, and use MC at the <b>optimal</b> quantity q*.',
 tryit:{q:'At the optimum, p* = 40 and MC(q*) = 30. Lerner index?',answer:0.25,tol:0.001,e:'(40 − 30) / 40 = 0.25, so |ε| = 1 / 0.25 = 4 at the optimum; markup µ = 40/30 ≈ 1.33.'}})}
${NOTION({id:'c1-welfare',title:'9. Is market power bad? Static and dynamic efficiency',
 ess:`<p>Market power causes <b>Pareto inefficiency</b>: static welfare (consumer + producer surplus) is maximal under perfect competition. But only <b>excessive</b> market power is shown to destroy welfare and lower the labour share. Some is warranted: consumers value <b>product differentiation</b>, and the prospect of monopoly power (patents) stimulates <b>innovation</b> (<b>dynamic efficiency</b>).</p>`,
 understand:`<ul><li><b>Pareto efficiency</b>: no agent can be made better off without making another worse off.</li>
 <li><b>Static societal welfare</b> = consumer surplus + producer surplus = area between the inverse demand curve and the MC curve, left of their intersection. It ignores distribution, the value of variety and technology accumulation.</li>
 <li><b>Patents</b> give a temporary monopoly so innovators can recover R&amp;D costs and be compensated for risk; without them, imitation would make innovation a public good, under-supplied by the market.</li>
 <li>Innovation arguments hold mostly when the <b>threat of entry is real</b>; a fully protected monopolist may simply “eat up” its profits.</li>
 <li>It is particularly <b>excessive</b> market power that destroys welfare and lowers the labour share (lower wages and/or employment).</li>
 <li>Policy must find a trade-off between static and dynamic efficiency (chapter 4: <b>effective competition</b>).</li></ul>`,
 trap:'“Perfect competition is Pareto-efficient” is a <b>static</b> statement with a given technology. It does not say that every market power is harmful.',
 tryit:{q:'Why do patents exist, according to the INSIGHTS?',o:['To create permanent monopolies','To give a temporary monopoly that rewards R&D and its risk, stimulating innovation','To lower prices for consumers'],a:1,e:'Temporary monopoly → recover research costs and risk → incentive to innovate (dynamic efficiency).'}})}
${C1_BIGTECH}
`;

SHEETS.c2=`
<div class="eyebrow">Midterm · Chapter 2 (also in the final)</div><h2>Strategic interaction under oligopoly</h2>
<p class="lede">Goal: find dominant strategies, equilibria in dominant strategies and Nash equilibria in a payoff matrix; solve sequential games by backward induction (SPNE, credible threats); explain repeated games, the paradox of Bertrand and Hotelling’s model.</p>
${YT}
${C2_WB}
${NOTION({id:'c2-seq',title:SEC('2.3','Sequential games, backward induction and credible threats'),
 ess:`<p>In a <b>sequential game</b>, later players observe earlier actions. It is drawn as a <b>game tree</b> and solved by <b>backward induction</b>: start with the last decision, then move back. The result is the <b>subgame-perfect Nash equilibrium (SPNE)</b>: the full strategy profile, including actions at nodes that are not reached. A <b>threat</b> matters only if <b>credible</b>: carrying it out must be rational when the node is reached.</p>`,
 extra:seqTree([[[6,4],[2,1]],[[3,2],[5,5]]],{solve:true,cap:'Main exercise: thick branches = choices of the SPNE (A; X after A, Y after B), path A → X, payoffs (6 ; 4).'}),
 understand:`${STEPS({title:'Backward induction on the main exercise',steps:['Last mover first: after A, Player 2 compares X (4) and Y (1) → X.','After B, Player 2 compares X (2) and Y (5) → Y.','Player 1 anticipates: A leads to (6 ; 4), B leads to (5 ; 5). 6 &gt; 5 → A.','SPNE = (A ; X after A, Y after B). Equilibrium path: A then X, payoffs (6 ; 4).','Credibility: a threat “I will play X after B” is not credible (2 &lt; 5). Player 2 would play X after B only if its payoff z there were above 5.']})}
 <p>The order of play does not always change the outcome: in the maintain-break game, the second mover still breaks (dominant strategy), so the first mover breaks too.</p>
 <p>${MIDP} Slides: a threat is credible “when the costs of falsely making a commitment are greater than the associated benefits”. <b>Strategic foresight</b>: a manager’s ability to make decisions today that are rational given what is anticipated in the future. <b>Subgame</b>: a segment of a larger game. <b>Commitment game</b>: the first player’s action is irreversible and observable by the second player, and the first player knows it is seen.</p>
 <h4>Credibility: the game trees of the slides (Varian)</h4>${VARIAN_STEPS.map(x=>STEPS(x)).join('')}`,
 example:['Cases on sequential games in digital markets (course solution)',T(['Case','SPNE','Outcome'],[['Amazon vs third-party seller','Seller: Stay out; Amazon: Imitate after Enter (8 &gt; 3, credible threat)','Stay out (0, 0); Amazon does not imitate if x &lt; 3'],['Apple App Store vs developer','Apple: Restrict; Developer enters after both','Restrict, Enter (8, 2); Apple opens if x &lt; 6'],['Uber vs Lyft','Uber: Low subsidy; Lyft enters after L, stays out after H','Low, Enter (5, 5): deterrence works but is too costly; High subsidy if x ≥ 5'],['Airbnb vs Booking.com','Airbnb: Low commission; Booking keeps after H and L','Low, Keep (9, 4); the cut threat is not credible (3 &lt; 4)']])],
 trap:'An SPNE is a <b>complete strategy</b>: give Player 2’s action after <b>each</b> possible move of Player 1 (“X after A, Y after B”), not just the equilibrium path.',
 tryit:{q:'Player 1 chooses A or B; then Player 2 chooses X or Y. Payoffs: (A,X) = (2,3), (A,Y) = (4,1), (B,X) = (3,2), (B,Y) = (1,4). What does Player 1 choose?',o:['A','B'],a:0,e:'After A, P2 plays X (3 &gt; 1) → P1 gets 2. After B, P2 plays Y (4 &gt; 2) → P1 gets 1. 2 &gt; 1, so A; SPNE (A ; X after A, Y after B).'}})}
${NOTION({id:'c2-centi',title:SEC('2.3','Centipede and ultimatum: theory versus behaviour'),extra:CENT_FIG,
 ess:`<p><b>Centipede</b>: backward induction makes A stop at once (2 ; 0) although continuing to the end gives (8 ; 6): an early decision depends on what can rationally be anticipated later (<b>strategic foresight</b>). <b>Ultimatum game</b>: theory predicts (9 ; 1); in experiments proposers offer more and responders reject unfair offers: fairness, reciprocity and reputation belong in the payoffs.</p>`,
 understand:`${STEPS({title:'Solving the six-stage centipede from right to left',intro:'<p>Stops pay, in order: A (2 ; 0), B (1 ; 3), A (4 ; 2), B (3 ; 5), A (6 ; 4), B (5 ; 7); if B continues at the end: (8 ; 6).</p>',steps:['Last node (B): stop gives 7, continue gives 6 → B stops.','Previous node (A): A anticipates B stops (5 for A); stopping gives 6 → A stops.','Previous node (B): B anticipates A stops (4 for B); stopping gives 5 → B stops.','Previous node (A): A anticipates B stops (3 for A); stopping gives 4 → A stops.','Previous node (B): B anticipates A stops (2 for B); stopping gives 3 → B stops.','First node (A): A anticipates B stops (1 for A); stopping gives 2 → A stops at once: (2 ; 0).']})}
 <p>Ultimatum: A proposes how to split 10 units (whole units); B accepts (split as proposed) or rejects (both get 0). If B cares only about money, B accepts any positive offer, so A offers 1: (9 ; 1). Observed behaviour differs, but this is not randomness: the payoffs must include fairness. The same holds for managers who care about reputation and regulators.</p>
 <p>Main insights (2.3.5): market structure alone does not determine conduct; timing, repetition, credible commitments and what decision-makers value matter.</p>
 <p>${MIDP} Observed: offers below 30% are rejected more than half the time; the average split is about 45% to the responder, with about 16% of offers rejected (slides). This does not make game theory useless: the solution depends only on the imposed assumptions (“it is math”), and any model is an approximation. Deviations from rationality listed in the slides: framing effects, irrelevant information, persistence in inferior choices, preferring few choices, inconsistency with uncertainty, trying to recover sunk costs, time inconsistency, lack of self-control, over-confidence, social norms.</p>`,
 trap:'The centipede does not prove that sequential interaction is always inefficient; it shows the power of backward induction <b>under its assumptions</b>.',
 tryit:{q:'Ultimatum game with 10 units and purely self-interested players: predicted split?',o:['(5 ; 5)','(9 ; 1)','(10 ; 0)'],a:1,e:'B accepts any strictly positive offer, so A offers the smallest whole unit: (9 ; 1).'}})}
${NOTION({id:'c2-bertrand',title:SEC('2.4','The paradox of Bertrand'),
 ess:`<p>A <b>homogeneous duopoly with price competition</b> ends in a price war until the price equals minimum average cost = marginal cost: <b>zero profit</b>, no market power, the same outcome as perfect competition, with only two firms.</p>`,
 understand:'<p>'+MIDP+' Differentiated oligopoly (smartphones, PCs, cars) is one of the most realistic market forms: firms compete on output, price and product positioning. Earlier models used <b>quantity</b> as the strategic variable; here it is <b>price</b>.</p>'+STEPS({title:'The price war, step by step',steps:['The product is identical: buyers only look at the price and all buy from the cheaper firm.','Firm 1 sets its price slightly below firm 2’s and captures the whole market.','Firm 2 reacts by undercutting firm 1, and so on.','The war stops only when the price exactly covers the costs: p = min AC = MC (constant returns to scale assumed in the chapter).','Profit is zero: the duopolists have no market power, as under perfect competition.']}),
 trap:'Bertrand needs <b>both</b> a homogeneous product <b>and</b> price as strategic variable. With differentiation (Hotelling), the price can stay above MC.',
 tryit:{q:'What allows firms to escape the paradox of Bertrand?',o:['Producing more','Product differentiation','Merging their cost functions'],a:1,e:'Hotelling: a differentiated product gives each firm a niche, so the price can rise above marginal cost.'}})}
${NOTION({id:'c2-hotel',title:SEC('2.4','Hotelling’s model: location as product differentiation'),
 ess:`<p>Ice-cream carts on a 2 km beach, sunbathers spread evenly, walking is costly. <b>Location = product differentiation; position of sunbathers = consumer preferences.</b> Socially optimal: carts 500 m from each end (average walk 250 m). With <b>fixed prices</b>, both move to the <b>centre</b>: minimal differentiation, a <b>homogeneous duopoly</b>, the unique <b>Nash equilibrium</b> (average walk 0.5 km). With <b>free prices</b>, the centre means Bertrand’s zero profit, so carts move apart to create a niche.</p>`,
 extra:`<div class="grid2">${beach(0.5,1.5,'Figure 2: socially optimal locations (heterogeneous duopoly)')}${beach(0.8,1.5,'Figure 3: under fixed prices, cart 1 moves right and steals customers')}${beach(1,1,'Figure 4: both carts at the centre: homogeneous duopoly (Nash equilibrium)')}${beach(0.7,1.3,'Figure 5: free prices: carts move away from the centre to escape Bertrand')}</div>${PLOT(HOTEL_PLOT)}<p class="hint">The beach above is also in the <b>Labs</b> tab. ${OUT} the walking distances of figures 3 and 5 are computed by the site.</p>`,
 understand:`<ul><li>A sunbather on the left would not walk past cart 1 to buy the same ice cream at cart 2: <b>geographical</b> differentiation gives each cart its own clientele, a <b>niche</b>, hence some market power.</li>
 <li><b>Fixed prices</b>: moving towards the centre loses no customer on your side and steals customers from the rival. Both end side by side at the centre: no one wants to move given the other’s location → unique NE → expected solution, though not socially optimal (0.5 km &gt; 250 m).</li>
 <li><b>Liberalized prices</b>: at the centre we have a homogeneous duopoly with price competition → price war (Bertrand) → zero profit. The centre is <b>no longer a NE</b>: each cart gains by moving away and pricing above MC for its niche.</li>
 <li>More (less) severe price competition → more (less) product differentiation, usually not maximal (not at the ends of the beach).</li></ul>`,
 trap:'Mock exam: “When duopolists do not engage in price competition, we expect the duopoly to be homogeneous” is answered with <b>Hotelling under fixed prices</b> (both carts at the centre = homogeneous duopoly = unique NE), <b>not</b> with the paradox of Bertrand (1 pt explanation + 0.5 pt NE).',
 tryit:{q:'Under fixed prices, why is (centre ; centre) the expected outcome?',o:['It minimizes the average walking distance','It is the unique Nash equilibrium: no cart gains by moving away given the other’s location','Prices fall to marginal cost there'],a:1,e:'Unique NE → expected solution. It is not socially optimal (average walk 0.5 km instead of 250 m).'}})}
`;

SHEETS.c3=`
<div class="eyebrow">Chapter 3</div><h2>Profit maximization under monopoly power</h2>
<p class="lede">Goal: derive cost and revenue functions, find q* from MR = MC, the price, the profit and the produce-or-shut-down decision; draw the monopoly graph; compute segmentation and first-degree price discrimination; describe monopolistic competition in the short and long run.</p>
${YT}
${NOTION({id:'c3-frame',title:'1. The firm’s problem and economic profit',
 ess:`${F('TR(q) = p(q)·q      Π(q) = TR(q) − TC(q)      p* = p(q*)')}<p>A firm with monopoly power is a <b>price setter</b>: it chooses q, and its demand curve gives the price. A monopolist faces the <b>market</b> demand; a firm under monopolistic competition the demand for its <b>differentiated</b> product. <b>Economic profit</b> includes implicit opportunity costs; accounting profit records only explicit costs.</p>`,
 understand:`<p>p(q) is the <b>inverse demand function</b>: the highest uniform price at which q units can be sold. Choosing q or choosing p is the same decision, since the demand curve links them.</p>`,
 tryit:{q:'Why can economic profit be lower than accounting profit?',o:['It ignores fixed costs','It also counts implicit opportunity costs','It is computed after taxes'],a:1,e:'Economic cost = explicit costs + opportunity costs of the resources used.'}})}
${NOTION({id:'c3-costs',title:'2. Short-run costs: FC, VC, AC, AFC, AVC, MC',
 ess:`${F('TC(q) = FC + VC(q)      AC = TC/q = AFC + AVC      AFC = FC/q      AVC = VC/q\nMC(q) = dTC/dq = dVC/dq   (FC does not change MC)')}<p><b>Short run</b>: at least one factor is fixed; <b>long run</b>: all factors adjustable (an economic, not a chronological distinction). Fixed cost must be paid even if the firm temporarily produces nothing.</p>`,
 extra:TWO(FIG({xmax:200,ymax:1400,xl:'q',yl:'€',curves:[{f:x=>200+2*x+0.02*x*x,c:'--debit',l:'TC'},{f:x=>2*x+0.02*x*x,c:'--ledger',l:'VC',lx:185}],marks:[{x:0,y:200,ly:'FC = 200'}]},'TC and VC have the same shape: the vertical gap is FC (Figure 1).'),FIG({xmax:200,ymax:25,xl:'q',yl:'€',curves:[{f:x=>200/x+2+0.02*x,c:'--warn',l:'AC',from:9,lx:30},{f:x=>2+0.02*x,c:'--muted',l:'AVC',dash:true,lx:185},{f:x=>2+0.04*x,c:'--ledger',l:'MC',lx:185},{f:x=>200/x,c:'--credit',l:'AFC',from:9,lx:20,dash:true}],marks:[{x:100,y:6,lx:'q = 100',ly:'min AC = 6'}],points:[{x:100,y:6}]},'AC = AFC + AVC; MC cuts AC at its minimum (Figure 2).')),
 understand:`<p>Fixed cost: buildings, machines, specialized staff. Variable cost: materials, energy, transport, production labour. AFC falls as output rises (the same FC is spread over more units).</p>
 <p>Graphically, <b>AC is the slope of the ray</b> from the origin to a point of the TC curve; <b>MC is the slope of the tangent</b> to TC at that point. For discrete changes, MC ≈ ΔTC/Δq.</p>`,
 example:['Lecture example (slides): TC(q) = 200 + 2q + 0.02q²',`${F('FC = 200   VC = 2q + 0.02q²   AC = 200/q + 2 + 0.02q   MC = 2 + 0.04q\nmin AC: 200/q + 2 + 0.02q = 2 + 0.04q → 200 = 0.02q² → q = 100,  AC(100) = MC(100) = 6')}${T(['q','TC','AC','MC','Comparison','Direction of AC'],[['10','222','22.2','2.4','MC &lt; AC','decreases'],['30','278','9.27','3.2','MC &lt; AC','decreases'],['60','392','6.53','4.4','MC &lt; AC','decreases'],['100','600','6','6','MC = AC','at its minimum'],['130','798','6.14','7.2','MC &gt; AC','increases'],['150','950','6.33','8','MC &gt; AC','increases'],['160','1 032','6.45','8.4','MC &gt; AC','increases']],[0,1,2,3])}`],
 trap:'MC = dTC/dq: the fixed cost disappears when you differentiate. A change in FC moves AC and AFC, never MC.',
 tryit:{q:'TC(q) = 50 + 4q + q². Marginal cost at q = 5?',answer:14,e:'MC = 4 + 2q = 4 + 10 = 14.'}})}
${NOTION({id:'c3-acmc',title:'3. Why MC crosses AC at its minimum',
 ess:`<p>If <b>MC &lt; AC</b>, the next unit costs less than the current average: AC <b>decreases</b>. If <b>MC &gt; AC</b>, AC <b>increases</b>. At an interior minimum, <b>MC = AC</b>. The same holds for MC and AVC. The minimum of MC is not the minimum of AC.</p>`,
 understand:`<p>The slides’ <b>cycling detour</b>: your average speed over the ride so far, and your marginal speed over the next small part. If your marginal speed is higher than your average, your average rises; if lower, it falls; if equal, it stays the same. Replace speed by cost per unit.</p>
 <p>Same idea with exam marks: a mark above your current average pulls the average up.</p>`,
 trap:'To find the minimum of AC, set <b>MC = AC</b> (or dAC/dq = 0), not MC = 0 and not AC = 0.',
 tryit:{q:'At q = 40, AC = 12 and MC = 9. If the firm produces one more unit, AC…',o:['increases','decreases','stays the same'],a:1,e:'MC &lt; AC: the next unit costs less than the average, so the average falls.'}})}
${NOTION({id:'c3-lr',title:'4. Long run: returns to scale and the scale-efficient quantity',
 ess:`${F('LAC(q) = LTC(q)/q      LMC(q) = dLTC/dq\nIncreasing returns (scale economies): LAC ↓, LMC < LAC\nConstant returns: LAC = LMC constant\nDecreasing returns (scale diseconomies): LAC ↑, LMC > LAC\nScale-efficient quantity qSE: min LAC, where LMC(qSE) = LAC(qSE)')}`,
 extra:`<div class="grid2">${FIG({xmax:10,ymax:10,xl:'q',yl:'€',curves:[{f:x=>2+12/(x+1.5),c:'--warn',l:'LAC',lx:8},{f:x=>2+12*1.5/((x+1.5)*(x+1.5)),c:'--ledger',l:'LMC',lx:3}]},'Increasing returns: LAC falls, LMC &lt; LAC (Figure 3)')}${FIG({xmax:10,ymax:10,xl:'q',yl:'€',curves:[{f:()=>5,c:'--warn',l:'LAC = LMC'}]},'Constant returns: LAC = LMC constant (Figure 4)')}${FIG({xmax:10,ymax:10,xl:'q',yl:'€',curves:[{f:x=>2+0.3*x,c:'--warn',l:'LAC',lx:9},{f:x=>2+0.6*x,c:'--ledger',l:'LMC',lx:8}]},'Decreasing returns: LAC rises, LMC &gt; LAC (Figure 5)')}${FIG({xmax:40,ymax:120,xl:'q',yl:'€',curves:[{f:x=>80-4*x+0.1*x*x,c:'--warn',l:'LAC',lx:36},{f:x=>80-8*x+0.3*x*x,c:'--ledger',l:'LMC',lx:34}],marks:[{x:20,y:40,lx:'qSE = 20',ly:'min LAC = 40'}],points:[{x:20,y:40}]},'U-shaped LAC, minimal at qSE (Figure 6; slides: LTC = 80q − 4q² + 0.1q³)')}</div>`,
 understand:`<p><b>Returns to scale</b> describe the technology (inputs → output); <b>economies of scale</b> describe the cost function. Increasing returns come from specialization and indivisible inputs; at a larger scale, coordination and control problems create decreasing returns. Hence the U-shaped LAC.</p>`,
 example:['Slides: the cookie producer (tabular exercise)',`${T(['q','LTC','LAC','Returns to scale (slide)'],[['100','€3 000','€30','IRS'],['200','€5 000','€25','IRS'],['300','€6 600','€22','IRS'],['400','€8 400','€21','CRS'],['500','€11 000','€22','DRS'],['600','€15 000','€25','DRS']],[0,1,2])}<p>LAC falls until q = 400, then rises: <b>qSE = 400</b>. From 100 to 200, LTC rises less than proportionally (scale economies); from 500 to 600, more than proportionally (diseconomies). If the market requires 1 200 boxes, <b>3 plants</b> of 400 minimize total cost (3 × 8 400 = 25 200).</p>
 <p>Slides, numerical: LTC = 80q − 4q² + 0.1q³ → LAC = 80 − 4q + 0.1q². Approach 1: dLAC/dq = −4 + 0.2q = 0 → q = 20. Approach 2: LMC = 80 − 8q + 0.3q² = LAC → 0.2q² = 4q → q = 20. Economies of scale below 20, diseconomies above.</p>`],
 trap:'qSE minimizes <b>long-run average</b> cost; it is not the profit-maximizing quantity. Its position relative to q* depends on demand and costs.',
 tryit:{q:'LTC(q) = 90q − 6q² + 0.2q³. Scale-efficient quantity qSE?',answer:15,e:'LAC = 90 − 6q + 0.2q²; dLAC/dq = −6 + 0.4q = 0 → q = 15.'}})}
${NOTION({id:'c3-rev',title:'5. Revenue side: TR, AR and MR',
 ess:`${F('TR(q) = p(q)·q      AR(q) = TR/q = p(q)   (AR = inverse demand)      MR(q) = dTR/dq\nLinear p = a − bq  →  MR = a − 2bq   (same intercept, twice the slope)')}<p>MR &lt; p: under uniform pricing, selling one more unit requires a lower price on <b>all</b> units. TR is an inverted U, maximal where <b>MR = 0</b>.</p>`,
 extra:TWO(FIG({xmax:2400,ymax:20000,xl:'q',yl:'€',curves:[{f:x=>30*x-0.0125*x*x,c:'--debit',l:'TR',lx:600}],marks:[{x:1200,y:18000,lx:'q = 1 200',ly:'TR max = 18 000'}],points:[{x:1200,y:18000}]},'TR for q = 2400 − 80p: maximal at q = 1 200'),FIG({xmax:2400,ymax:32,xl:'q',yl:'€',curves:[{f:x=>30-0.0125*x,c:'--debit',l:'AR = p(q)',lx:1900},{f:x=>30-0.025*x,c:'--credit',l:'MR',to:1200,lx:500}],marks:[{x:1200,y:15,lx:'MR = 0 at 1 200',ly:'p = 15'}]},'AR and MR: same intercept, MR twice as steep (Figure 8)')),
 understand:`<p>Output changes TR in two ways: directly (one more unit sold at price p) and indirectly (the price of all units falls). That second effect is why MR is below the price. Table 1 of the INSIGHTS shows it with discrete steps of 100 units:</p>
 ${T(['Price','q','TR','ΔTR','ΔTR/Δq'],[['20','800','16 000','—','—'],['18.75','900','16 875','875','8.75'],['17.5','1 000','17 500','625','6.25'],['16.25','1 100','17 875','375','3.75'],['15','1 200','18 000','125','1.25'],['13.75','1 300','17 875','−125','−1.25'],['12.5','1 400','17 500','−375','−3.75']],[0,1,2,3,4])}`,
 example:['INSIGHTS: books, q = 2400 − 80p',F('Inverse demand: 80p = 2400 − q → p = 30 − 0.0125q\nTR = 30q − 0.0125q²    AR = 30 − 0.0125q    MR = 30 − 0.025q\nMR = 0 → q = 1 200, p = 15, TR = 18 000')],
 trap:'Invert the demand function first: from q = 2400 − 80p to p = 30 − 0.0125q. MR is computed from p(q), not from q(p).',
 tryit:{q:'q = 600 − 20p. Marginal revenue MR(q) has which slope?',o:['−0.05','−0.1','−20','−40'],a:1,e:'p = 30 − 0.05q, so MR = 30 − 0.1q: twice the slope of the inverse demand.'}})}
${NOTION({id:'c3-rule',title:'6. Step 1: the profit-maximizing quantity, MR = MC',
 ess:`${F('Marginal profit MP(q) = dΠ/dq = MR(q) − MC(q)\nStep 1: MR(q*) = MC(q*)   (necessary; check MR > MC just below q*, MR < MC just above)')}<p>If MR &gt; MC, one more unit raises profit; if MR &lt; MC, it lowers profit. With MR decreasing and MC non-decreasing there is at most one intersection. When MC &gt; 0, profit maximization comes <b>before</b> revenue maximization (MR(q*) = MC &gt; 0).</p>`,
 extra:FIG({xmax:1300,ymax:20000,xl:'q',yl:'€',curves:[{f:x=>30*x-0.0125*x*x,c:'--debit',l:'TR',lx:1050},{f:x=>63+20*x,c:'--credit',l:'TC',lx:900}],marks:[{x:400,y:10000,lx:'q* = 400'}],lines:[{x1:400,y1:8063,x2:400,y2:10000,c:'--ok',w:4}],points:[{x:6.35,y:190,l:'break-even'},{x:793.6,y:15935,l:'break-even',left:true}]},'Figure 9: profit = vertical distance between TR and TC, largest at q* where the slopes are equal (MR = MC).'),
 understand:`<p>Between the two break-even quantities, TR &gt; TC. To the left of q*, MR &gt; MC so the gap widens; to the right, it narrows. At q*, TR and TC have the same slope. With a U-shaped MC, MR and MC can cross twice: then check the second-order condition and compare profits.</p>`,
 trap:'MR = MC gives the <b>quantity</b>. The <b>price</b> is read on the <b>demand</b> curve at q*, never on the MR or MC curve.',
 tryit:{q:'p(q) = 50 − 2q and MC = 10. Profit-maximizing quantity?',answer:10,e:'MR = 50 − 4q = 10 → q* = 10 (then p* = 30).'}})}
${NOTION({id:'c3-produce',title:'7. Step 2: produce q* or nothing?',
 ess:`${F('Long run:  produce if TR(q*) ≥ TC(q*)  ⇔  p* ≥ AC(q*)   otherwise exit\nShort run: produce if TR(q*) ≥ VC(q*)  ⇔  p* ≥ AVC(q*)  otherwise shut down temporarily\nProfit Π = q*[p* − AC(q*)] = q*[p* − AVC(q*)] − FC')}`,
 understand:`<p>In the short run the fixed cost is paid <b>whether or not</b> the firm produces, so it does not affect the comparison: producing is worth it as long as revenue covers the variable cost (each unit then contributes to the fixed cost). In the long run nothing is fixed: the firm stays only if revenue covers all costs.</p>`,
 example:['INSIGHTS: p(q) = 30 − 0.0125q, TC = 63 + 20q',`${F('MR = 30 − 0.025q = 20 = MC → q* = 400, p* = 25\nAVC = 20 < 25 → produce in the short run.  Π = 10 000 − 8 063 = 1 937 = 400(25 − 20) − 63')}${FIG(monoSpec(30,0.0125,20,0,63,{xmax:2400,ymax:32}).spec,'Figure 10: q* where MR = MC, p* on the demand curve; shaded: profit q*[p* − AC(q*)].')}`],
 trap:'Short run: compare with <b>AVC</b>; long run: with <b>AC</b>. A firm can rationally produce at a loss in the short run (p between AVC and AC).',
 tryit:{q:'At q*, p* = 12, AVC = 10 and AC = 13. Short-run decision?',o:['Shut down: it makes a loss','Produce: p* ≥ AVC, the loss is smaller than FC','Exit at once'],a:1,e:'p* ≥ AVC: revenue covers variable costs and part of FC. In the long run (p &lt; AC) it would exit.'}})}
${NOTION({id:'c3-graph',title:'8. The monopoly graph (mock exam Q3)',
 ess:`<p>Draw <b>p(q)</b>, <b>MR</b> (same intercept, twice the slope), <b>MC</b> and <b>AC</b>. q* where MR crosses MC; p* on the <b>demand curve</b> above q*; shaded profit = rectangle between p* and AC(q*) over q*. Market power: p* &gt; MC(q*).</p>`,
 extra:FIG(monoSpec(17,1,5,1,0,{xmax:9,ymax:18}).spec,'Mock exam Q3: p(q) = 17 − q, TC = 5q + q². q* = 3, p* = 14, shaded profit 3 × (14 − 8) = 18.'),
 understand:`<p>Move the sliders of the <b>Monopoly</b> graph in the Tools tab: a higher MC slope or a lower demand reduces q*, the price adjusts on the demand curve, and the profit rectangle changes.</p>`,
 example:['Mock exam Q3: the Sound of Economics T-shirts (2 + 0.5 + 0.5 + 0.5 + 0.5 + 2 points)',F('a) AVC = VC/q = 5 + q\nb) MR = 17 − 2q, MC = 5 + 2q → 17 − 2q = 5 + 2q → q* = 3\nc) p* = 17 − 3 = 14\nd) Π = TR − TC = 42 − (15 + 9) = 18\ne) p* = 14 > MC(3) = 11: market power (markup 14/11 > 1)\nf) graph: 0.5 curves, 0.5 q* at MR = MC, 0.5 p* on the demand curve, 0.5 profit area')],
 trap:'Profit rectangle: height p* − AC(q*), not p* − MC(q*). Without fixed cost, AC = AVC.',
 tryit:{q:'p(q) = 20 − q, TC = 2q + q². Maximum profit?',answer:40.5,tol:0.01,e:'MR = 20 − 2q = 2 + 2q → q* = 4.5; p* = 15.5; AC = 2 + 4.5 = 6.5; Π = 4.5 × (15.5 − 6.5) = 40.5.'}})}
${NOTION({id:'c3-first',title:'9. First-degree price discrimination',
 ess:`<p>Each buyer pays his <b>maximal willingness to pay</b> (WTP). The marginal revenue of a sale = its price, so the monopolist sells to everyone with <b>WTP ≥ MC</b>. Consumer surplus is entirely skimmed (<b>CS = 0</b>), profit is maximal, output equals perfect competition (Pareto-efficient), but it is highly doubtful on distributional and ethical grounds.</p>`,
 extra:TWO(FIG({xmax:2400,ymax:32,xl:'q',yl:'€',curves:[{f:x=>30-0.0125*x,c:'--debit',l:'p(q) = WTP',lx:1700},{f:()=>20,c:'--ledger',l:'MC',lx:2100}],areas:[{pts:[[0,30],[0,20],[800,20]],c:'--ok',l:'Profit'}],marks:[{x:800,y:20,lx:'q = 800'}]},'First degree: sell until WTP = MC; the whole area above MC is profit.'),FIG({xmax:2400,ymax:32,xl:'q',yl:'€',curves:[{f:x=>30-0.0125*x,c:'--debit',l:'p(q)',lx:1700},{f:x=>30-0.025*x,c:'--credit',l:'MR',to:1200,lx:900},{f:()=>20,c:'--ledger',l:'MC',lx:2100}],areas:[{pts:[[0,30],[0,25],[400,25]],c:'--debit',l:'CS'},{pts:[[0,20],[0,25],[400,25],[400,20]],c:'--ok',l:'Profit'}],marks:[{x:400,y:25,lx:'q* = 400',ly:'p* = 25'}]},'Uniform price: consumers keep a surplus (CS).')),
 understand:`<p>Under a uniform price, everybody except the last buyer pays less than his WTP: a <b>consumer surplus</b>. Price discrimination (different prices for the same product) skims it. In Figure 11 of the INSIGHTS, four customers each pay their own WTP; nobody with a WTP below that of Bill (below MC) is served.</p>
 <p class="hint">${OUT} the two graphs apply the course rule to the INSIGHTS demand p = 30 − 0.0125q with MC = 20: first degree sells 800 units, profit 0.5 × 800 × 10 = 4 000 (minus FC) against 2 000 under the uniform price.</p>`,
 trap:'Under first degree, output is the <b>perfect-competition</b> output (WTP = MC), not the monopoly q*. Static welfare is maximal; distribution is not.',
 tryit:{q:'Under first-degree price discrimination, the consumer surplus is…',o:['maximal','zero','the same as under a uniform price'],a:1,e:'Each buyer pays his WTP: the whole surplus becomes producer surplus.'}})}
${NOTION({id:'c3-seg',title:'10. Market segmentation',
 ess:`<p>Divide buyers into groups with different elasticities (age, country) and apply <b>MR<sub>i</sub>(q<sub>i</sub>) = MC</b> in each segment. The <b>more elastic</b> segment gets the <b>lower</b> price and the higher quantity. Profit is at least as high as under uniform pricing. Condition: <b>resale between groups must be (nearly) impossible</b> (medical procedures; countries with high transport costs or duties).</p>`,
 extra:TWO(FIG({xmax:20,ymax:12,xl:'q₁',yl:'€',curves:[{f:x=>10-0.5*x,c:'--debit',l:'p₁ youngsters',lx:15},{f:x=>10-x,c:'--credit',l:'MR₁',to:10,lx:7},{f:()=>6,c:'--ledger',l:'MC = 6',lx:18}],marks:[{x:4,y:8,lx:'q₁ = 4',ly:'p₁ = 8'}],points:[{x:4,y:8}]},'Segment 1 (more elastic): lower price'),FIG({xmax:16,ymax:17,xl:'q₂',yl:'€',curves:[{f:x=>16-x,c:'--debit',l:'p₂ adults',lx:12},{f:x=>16-2*x,c:'--credit',l:'MR₂',to:8,lx:6},{f:()=>6,c:'--ledger',l:'MC = 6',lx:14}],marks:[{x:5,y:11,lx:'q₂ = 5',ly:'p₂ = 11'}],points:[{x:5,y:11}]},'Segment 2 (less elastic): higher price')),
 understand:`<p>With one uniform price, MR = MC holds for the combined market but generally not in each segment. If the last youngster unit brings more MR than the last adult unit, moving sales towards youngsters (lower price there) and away from adults (higher price) raises profit, until MR<sub>1</sub> = MR<sub>2</sub> = MC (mock exam Q1b).</p>`,
 example:['INSIGHTS: youngsters and adults, MC = 6',F('q1 = 20 − 2p1 (p1 = 10 − 0.5q1), q2 = 16 − p2 (p2 = 16 − q2)\nUniform: q = 36 − 3p → p = 12 − q/3, MR = 12 − (2/3)q = 6 → q* = 9, p* = 9, Π = 81 − 54 = 27\nSegment 1: MR1 = 10 − q1 = 6 → q1 = 4, p1 = 8 (lower than 9)\nSegment 2: MR2 = 16 − 2q2 = 6 → q2 = 5, p2 = 11 (higher than 9)\nΠ = 32 + 55 − 54 = 33 > 27')],
 trap:'The market demand under uniform pricing is the <b>horizontal sum</b> of the segment demands q(p) = q1(p) + q2(p), valid only for prices at which both segments buy. Add the quantities, never the prices.',
 tryit:{q:'Segment A has |ε| = 3, segment B has |ε| = 1.5 at current prices. Which segment gets the higher price?',o:['A','B'],a:1,e:'The less elastic segment (B) is charged the higher price.'}})}
${NOTION({id:'c3-moncomp',title:'11. Monopolistic competition: short run and long run',
 ess:`<p><b>Short run</b>: given number of firms; each sets MR<sub>SR</sub> = MC on its own demand; profit can be positive, zero or negative. <b>Long run</b>: MR = MC <b>and</b> p = AC (zero economic profit): the demand curve is <b>tangent</b> to AC. Still p &gt; MC (market power remains) and AC is still decreasing: firms produce less than q<sub>SE</sub> (unused scale economies), in exchange for product variety.</p>`,
 extra:TWO(FIG(Object.assign(monoSpec(26,1.5,2,0,64,{xmax:17.3,ymax:28}).spec,{}),'Figure 15, short run: p > AC(q), positive profit (illustrative curves).'),FIG(monoSpec(18,1,2,0,64,{xmax:18,ymax:28}).spec,'Figure 16, long run: entry pushes demand down until it is tangent to AC: zero profit, p = AC > MC.')),
 understand:`<p>Why <b>tangency</b> and not just an intersection of demand and AC? Zero profit must coincide with the <b>maximum</b> attainable profit. If the demand crossed AC, some quantity between the crossings would give positive profit and entry would continue. At the tangency point, every other quantity gives a loss, and MR = MC there.</p>
 <p class="hint">${OUT} the curves are illustrative (demand 26 − 1.5q then 18 − q, AC = 64/q + 2, MC = 2); the INSIGHTS give no numbers.</p>`,
 trap:'Zero economic profit does <b>not</b> remove market power: p &gt; MC in the long run, because MR &lt; p on a downward-sloping demand.',
 tryit:{q:'In the long-run equilibrium of monopolistic competition, which statement is right?',o:['p = MC and p = AC','p = AC > MC, and the firm produces less than qSE','p > AC and profit is positive'],a:1,e:'Tangency of demand and AC on the decreasing part of AC: zero profit, but p &gt; MC and q &lt; qSE.'}})}
`;

SHEETS.c4=`
<div class="eyebrow">Chapter 4</div><h2>Profit maximization under perfect competition</h2>
<p class="lede">Goal: find the output and profit of a price taker, move from an initial market situation to the market equilibrium with free entry and exit (price, output per firm, total output, number of firms), explain natural monopoly and why perfect competition is not so perfect.</p>
${YT}
${NOTION({id:'c4-taker',title:'1. The price taker: p = AR = MR',
 ess:`${F('TR = p·q      AR = TR/q = p      MR = dTR/dq = p      ⇒  p = AR = MR')}<p>The market price is set by market demand and market supply; the individual firm cannot affect it. <b>Market</b> demand slopes down, but the demand faced by <b>one</b> firm is <b>horizontal</b> at the market price (|ε| = ∞).</p>`,
 extra:TWO(FIG({xmax:40,ymax:20,xl:'Q (market)',yl:'p',curves:[{f:x=>20-x/2,c:'--debit',l:'D',lx:30},{f:x=>x/2,c:'--ledger',l:'S',lx:34}],marks:[{x:20,y:10,lx:'Q = 20',ly:'p = 10'}],points:[{x:20,y:10}]},'The market sets the price…'),FIG({xmax:10,ymax:20,xl:'q (one firm)',yl:'p',curves:[{f:()=>10,c:'--debit',l:'demand of the firm: p = MR = AR',lx:5}]},'…the firm faces a horizontal demand at that price (Figure 1).')),
 understand:`<p>Charge more than the market price: every buyer goes to another seller of the identical product. Charge less: pointless, since you can sell everything at the market price.</p>`,
 tryit:{q:'For a price-taking firm, marginal revenue equals…',o:['the market price','twice the price','zero'],a:0,e:'Each extra unit sells at the same market price: MR = AR = p.'}})}
${NOTION({id:'c4-qstar',title:'2. Profit maximization: p = MC, then produce or not',
 ess:`${F('Profit maximum: p = MC(q*)  (with MC increasing)\nAll costs avoidable: produce if p ≥ AC(q*), else exit\nShort run with an unavoidable FC: produce if p ≥ AVC(q*), else shut down\nΠ = q*[p − AC(q*)]')}<p>At p = min AC the firm is indifferent between producing at q<sub>SE</sub> and staying out.</p>`,
 extra:FIG(takerSpec(0,2,2,10,{xmax:4,ymax:14}).spec,'INSIGHTS example: TC = 2q + 2q², p = 10 → q* = 2, AC(2) = 6, profit 2 × (10 − 6) = 8 (Figure 2).'),
 understand:`<p>When MC(q) &lt; p, one more unit adds more revenue (p) than cost: produce it. When MC(q) &gt; p, it lowers profit. Hence p = MC on the <b>increasing</b> part of MC.</p>`,
 example:['INSIGHTS: TC(q) = 2q + 2q², p = 10 (slide steps)',F('Step 1: MC(q) = 2 + 4q\nStep 2: p = MC → 10 = 2 + 4q* → q* = 2\nStep 3: produce? AC(q*) = 2 + 2q* = 6 < 10 → yes.  Π = 2(10 − 6) = 8')],
 trap:'Under perfect competition the rule is <b>p = MC</b>, not MR = MC with a sloping MR: the firm has no market power (p = MC, markup 1).',
 tryit:{q:'TC(q) = 16 + 4q + q², p = 20. Profit-maximizing output q*?',answer:8,e:'MC = 4 + 2q = 20 → q* = 8 (the cookie producer of the mock exam).'}})}
${NOTION({id:'c4-supply',title:'3. The supply curve of the firm',
 ess:`<p>For every price, the firm produces where p = MC, if it operates. All costs avoidable: its supply curve is the <b>increasing part of MC at and above min AC</b>; below min AC it supplies zero. With an unavoidable fixed cost in the short run, the threshold is <b>min AVC</b>.</p>`,
 extra:FIG({xmax:12,ymax:30,xl:'q',yl:'p',curves:[{f:x=>16/x+4+x,c:'--warn',l:'AC',from:0.6,lx:10.5},{f:x=>4+2*x,c:'--muted',l:'MC below min AC',to:4,dash:true,lx:1.5},{f:x=>4+2*x,c:'--ledger',l:'supply = MC above min AC',from:4,lx:9}],marks:[{x:4,y:12,lx:'qSE = 4',ly:'min AC = 12'}],points:[{x:4,y:12}],lines:[{x1:0,y1:0,x2:0,y2:12,c:'--ledger',w:4}]},'Figure 3 with the cookie costs TC = 16 + 4q + q²: zero supply below p = 12, then the MC curve.'),
 tryit:{q:'Cookie producer, TC = 16 + 4q + q² (16 avoidable). Below which price does the firm supply nothing?',answer:12,e:'min AC: 16/q + 4 + q = 4 + 2q → q = 4, AC = 12.'}})}
${NOTION({id:'c4-entry',title:'4. From the initial market situation to market equilibrium',
 ess:`${F('Market equilibrium with free entry and exit (identical firms):\n1. p* = MC(q*)            (profit maximization)\n2. QD(p*) = n*·q*          (market clearing)\n3. Π(q*) = 0 ⇔ p* = AC(q*)  (stable number of firms)\n⇒ MC(q*) = AC(q*):  q* = qSE,  p* = min AC,  Q* = QD(p*),  n* = Q*/q*')}<p><b>Market clearing ≠ stable number of firms.</b> Positive profit → entry → supply shifts right → price falls. Losses → exit → supply shifts left → price rises. Entry stops at zero economic profit.</p>`,
 extra:FIG({xmax:30,ymax:20,xl:'Q',yl:'p',curves:[{f:x=>20-x/2,c:'--debit',l:'QD = 40 − 2p',lx:5},{f:x=>2*x/4,c:'--muted',l:'S, 4 firms',lx:27,dash:true},{f:x=>2*x/5,c:'--muted',l:'5 firms',lx:28.5,dash:true},{f:x=>2*x/6,c:'--ledger',l:'6 firms',lx:29}],marks:[{x:20,y:10,ly:'p0 = 10'},{x:24,y:8,lx:'Q* = 24',ly:'p* = 8'}],points:[{x:20,y:10,l:'initial'},{x:22.22,y:8.889},{x:24,y:8,l:'equilibrium'}]},'No Grain, No Gain: entry shifts market supply to the right (4 → 5 → 6 firms) and lowers the price from 10 to 8 (Figures 4 to 6).'),
 understand:`<p>Watch it move in the Tools tab (<b>From the initial market to equilibrium</b>): change the number of firms and see the price, the output per firm and the profit.</p>
 <p>Zero economic profit does <b>not</b> mean the entrepreneur earns nothing: economic cost includes the opportunity cost of his resources, so zero economic profit includes a <b>normal return</b>.</p>`,
 example:['INSIGHTS: No Grain, No Gain',`${F('QD(p) = 40 − 2p,  TC = 16 + q² (16 avoidable),  MC = 2q,  AC = 16/q + q\nInitial: p0 = 10 → q0 = 5, Π = 50 − 41 = 9; 4 firms supply 20 = QD(10): the market clears but firms earn profit\n5 firms: 40 − 2p = 5(p/2) → p = 80/9 ≈ 8.889, q ≈ 4.44, profit still > 0 → entry continues\nEquilibrium: 16/q + q = 2q → q* = 4, p* = 8, Q* = 40 − 16 = 24, n* = 24/4 = 6, Π = 0')}${T(['Variable','Initial situation','Market equilibrium'],[['Market price','10','8'],['Output per firm','5','4'],['Total market output','20','24'],['Number of firms','4','6'],['Economic profit per firm','9','0']],[1,2])}<p>Entry lowers the price and the output per firm, raises the number of firms and total output.</p>`],
 trap:'Mock exam Q4: first the <b>initial</b> situation (p0 = MC → q0, profit, Q0 = QD(p0), n0 = Q0/q0, direction of entry/exit), then the <b>equilibrium</b> (MC = AC → q*, p*, Q*, n*). Do not use MC = AC for the initial situation.',
 tryit:{q:'Mock exam Q4: TC = 16 + 4q + q², QD = 52 − p, p0 = 20. Initial number of producers n0?',answer:4,tol:0,e:'q0 = 8 (20 = 4 + 2q), Q0 = 52 − 20 = 32, n0 = 32/8 = 4. Equilibrium: q* = 4, p* = 12, Q* = 40, n* = 10.'}})}
${NOTION({id:'c4-natmono',title:'5. Natural monopoly',
 ess:`<p>Free entry does not always give many firms. A <b>natural monopoly</b> arises when there is no price equal to minimum average cost at which two or more firms can each sell enough to cover their costs: large economies of scale, <b>q<sub>SE</sub> large relative to market demand</b>. The remaining firm then faces the market demand and sets MR = MC: lower quantity, higher price, positive profit.</p>`,
 extra:FIG({xmax:2000,ymax:46,xl:'q',yl:'€',curves:[{f:x=>45-x/40,c:'--debit',l:'market demand',lx:1500},{f:x=>45-x/20,c:'--credit',l:'MR',to:900,lx:700},{f:x=>5000/x+5+0.005*x,c:'--warn',l:'LAC',from:130,lx:1800},{f:x=>5+0.01*x,c:'--ledger',l:'LMC',lx:1900}],marks:[{x:1000,y:15,lx:'qSE = 1 000',ly:'min LAC = 15'},{x:666.7,y:28.33,ly:'pM'}],points:[{x:1000,y:15},{x:1200,y:15,l:'QD(15) = 1 200'},{x:666.7,y:28.33,l:'monopoly'}],vx:[{x:200,l:'residual 200',c:'--muted',dash:true}]},'Figures 8–10: min LAC = 15 at qSE = 1 000, demand at 15 = 1 200. A second firm would serve only 200 units at an AC far above 15.'),
 understand:`<p>Thought experiment of the INSIGHTS: two scale-efficient firms would supply 2 000 units, more than the 1 200 demanded at 15. If one firm produces 1 000, only 200 remain; a second firm producing 200 has AC &gt; 15 and cannot break even. Entry is possible but not profitable, so the price-taking structure is not sustainable.</p>
 <p>Tension: one firm avoids duplicating costs (efficient on costs) but has market power (price above MC).</p>
 <p class="hint">${OUT} the curves use LTC = 5 000 + 5q + 0.005q² and QD = 1 800 − 40p, chosen to match the INSIGHTS figures (min LAC 15 at 1 000; demand 1 200 at 15).</p>`,
 trap:'Natural monopoly depends on costs <b>and</b> on the size of demand: the same technology can support many firms in a large market.',
 tryit:{q:'min LAC = 20 at qSE = 500; market demand at p = 20 is 1 800. Is it a natural monopoly?',o:['Yes','No: the market can support 3 scale-efficient firms'],a:1,e:'1 800 / 500 = 3.6: at least 3 firms can each produce 500 at min LAC.'}})}
${NOTION({id:'c4-shocks',title:'6. Why perfect competition is not so perfect',
 ess:`<p><b>Demand shocks</b>: output already produced cannot adjust; the price falls until buyers take it, possibly below AC (losses), and a price taker cannot protect itself (potato market exercise). <b>Cost shocks</b>: MC and AC shift up, market supply shifts left: higher price, lower quantity, losses then exit (shipping-cost exercise). <b>Static vs dynamic efficiency</b>: p = MC is statically efficient; market power creates a short-run welfare loss but can reward and finance innovation. Goal: <b>effective competition</b>.</p>`,
 understand:`<p>The policy objective is not perfect competition at every moment, but competition that limits persistent market power while allowing a reasonable reward for innovation: balance static and dynamic efficiency.</p>`,
 tryit:{q:'Energy prices rise for all producers of a competitive market. Expected effect?',o:['Lower price, higher quantity','Higher price, lower quantity; some firms may exit','No effect: price takers do not react'],a:1,e:'MC and AC up → supply shifts left → higher price, lower quantity; persistent losses → exit.'}})}
`;

SHEETS.cheat=`
<div class="eyebrow">One page</div><h2>Cheat sheet</h2>
${T(['What','Formula / rule'],[
['Price elasticity','ε = %Δq / %Δp; elastic |ε| > 1, inelastic |ε| < 1'],
['Markup, Lerner','µ = p*/MC(q*) > 1 ⇔ market power; (p − MC)/p = 1/|ε|'],
['Costs','AC = TC/q, AVC = VC/q, AFC = FC/q, MC = dTC/dq; MC cuts AC at min AC'],
['Long run, qSE','LAC = LTC/q, LMC = dLTC/dq; qSE where LMC = LAC (or dLAC/dq = 0); IRS: LAC ↓, LMC < LAC; DRS: LAC ↑, LMC > LAC'],
['Revenue','TR = p(q)q, AR = p(q), MR = dTR/dq; linear p = a − bq → MR = a − 2bq; TR max at MR = 0'],
['Monopoly / price setter','MR(q*) = MC(q*), p* = p(q*), Π = q*(p* − AC(q*))'],
['Produce or not','long run p* ≥ AC; short run p* ≥ AVC'],
['Segmentation','MRi(qi) = MC in each segment; elastic segment → lower price'],
['First degree','price = WTP; sell while WTP ≥ MC; CS = 0; output = perfect competition'],
['Monopolistic competition (long run)','MR = MC and p = AC: demand tangent to AC; p > MC, q < qSE'],
['Price taker','p = AR = MR = MC(q*)'],
['Market equilibrium','p* = MC = AC → q* = qSE, p* = min AC; Q* = QD(p*); n* = Q*/q*'],
['Natural monopoly','qSE large relative to QD(min AC): second firm’s residual demand has AC > p']])}
${T(['Game theory','Rule'],[['Dominant strategy','best whatever the other does'],['Nash equilibrium','no player wants to change, given the other’s strategy; mark best responses'],['Expected solution','a unique NE; several NE → none without coordination'],['Sequential game','tree + backward induction; SPNE lists actions at every node'],['Credible threat','optimal when the node is reached'],['Bertrand','homogeneous + price competition → p = MC, zero profit'],['Hotelling','fixed prices → both at the centre (homogeneous, NE); free prices → differentiation']])}
<h3>Exam checklist</h3>
<ol><li>Every definition asked must be written out: answers count only if the explanation or definition is correct (mock exam).</li>
<li>Calculations: write the functions (MC, AC, MR) before solving; check p ≥ AVC / AC; give units.</li>
<li>Graphs: draw p(q), MR, MC, AC; mark q* at MR = MC, p* on the demand curve, shade the profit rectangle between p* and AC(q*).</li>
<li>Games: underline best responses, then state dominant strategies, NE, expected solution and SPNE in the requested form.</li>
<li>Market equilibrium: initial situation (p0 = MC, profit, n0 = Q0/q0) → direction of entry/exit → p* = MC = AC → Q* → n*.</li></ol>
`;

/* ---------- quiz ---------- */
const TF=['True','False'];
const Q=(id,topic,src,q,o,a,e)=>({id,topic,src,q,o,a,e});
const QUIZ=[
Q('q0','c1','course','True or false: in a monopoly and under perfect competition, there is no strategic interaction; this is not the case under oligopoly.',TF,0,'TRUE (solution 1.1): the monopolist has no rival; a perfectly competitive firm is a price taker; an oligopolist must take a few rivals’ reactions into account.'),
Q('q1','c1','course','True or false: because of product differentiation in a setting with many firms, each company has a demand curve that is not horizontal.',TF,0,'TRUE (1.3): products are imperfect substitutes, so each firm’s demand slopes downward.'),
Q('q2','c1','course','True or false: in a setting with many firms, product differentiation is a promising strategy to ensure at least some market power.',TF,0,'TRUE (1.4): differentiation reduces substitutability; the firm can raise its price without losing all customers.'),
Q('q3','c1','course','True or false: a strong image will imply that the price elasticity will increase in absolute terms, making it possible for the brand to receive a premium over the normal price.',TF,1,'FALSE (1.5): a strong image makes demand <b>less</b> price sensitive; |ε| decreases, which allows the price premium.'),
Q('q4','c1','course','1. The lipstick market can usually be considered as a market with monopolistic competition. 2. Legal constraints are an example of a barrier to entry in a market with monopolistic competition.',['1 is TRUE; 2 is FALSE','1 and 2 are TRUE','1 is FALSE; 2 is TRUE','1 and 2 are FALSE'],0,'(b) in the official solution 1.6: monopolistic competition has relatively free entry, so legal barriers contradict its definition.'),
Q('q5','c1','course','1. Price elasticity measures the relative change in demand for a good after a relative change in its price. 2. Price elasticity is always positive.',['1 is TRUE, 2 is FALSE','1 and 2 are TRUE','1 is FALSE, 2 is TRUE','1 and 2 are FALSE'],0,'1.A1 (b): elasticity is usually negative.'),
Q('q6','c1','course','1. Price elasticity measures the percentage change in price after a percentage change in demand. 2. Perfect price elasticity occurs when price elasticity is in absolute value lower than one.',['1 and 2 are FALSE','1 and 2 are TRUE','1 is TRUE, 2 is FALSE','1 is FALSE, 2 is TRUE'],0,'1.A2 (d): it is the % change in <b>demand</b> after a % change in price; perfectly elastic means |ε| = ∞.'),
Q('q7','c1','course','1. In monopoly firms are price setters, while in monopolistic competition firms are price takers. 2. Market power is a characteristic of perfect competition.',['1 and 2 are FALSE','1 and 2 are TRUE','1 is TRUE, 2 is FALSE','1 is FALSE, 2 is TRUE'],0,'1.A3 (d): firms under monopolistic competition are (limited) price setters; perfect competition means no market power.'),
Q('q8','c1','course','Which characteristics correspond to a perfectly competitive market? 1 market atomism; 2 complete information; 3 homogeneity; 4 barriers to entry.',['1, 2 and 3','1 and 2','2 and 3','1, 2 and 4'],0,'1.A4 (c): the fourth condition is free entry and exit, not barriers.'),
Q('q9','c1','course','Which are barriers to entry that can help maintain a monopoly? 1 economies of scale; 2 exclusive usage rights; 3 strategic actions such as expensive marketing; 4 network externalities.',['1, 2, 3 and 4','1 and 2','2 and 3','1, 3 and 4'],0,'1.A5 (d): the four types of barriers in the INSIGHTS.'),
Q('q10','c1','practice','Indila, dying of thirst in the desert, still buys the bottle of water when its price jumps from €1 to €1 000. Her demand is close to:',['perfectly inelastic','perfectly elastic','unitary elastic','elastic'],0,'Demand does not react to price: |ε| ≈ 0.'),
Q('q11','c1','practice','The price elasticity of apples in the U.S. is −1.159. Demand for apples is:',['elastic','inelastic','perfectly inelastic','unitary elastic'],0,'|ε| = 1.159 > 1: a 1% price rise lowers demand by 1.159%.'),
Q('q12','c1','practice','According to Table 1 of the INSIGHTS, which demand is the most price inelastic?',['Gasoline in the short run (−0.01 to −0.2)','Gasoline in the long run (−0.4 to −0.8)','Regular economy US–Europe flights (−1.30)','Beer and malt beverages (−2.83)'],0,'Short-run gasoline demand barely reacts: |ε| ≤ 0.2.'),
Q('q13','c1','practice','The markup µ is defined as:',['p*(q*) / MC(q*)','MC(q*) / p*(q*)','p*(q*) − AC(q*)','(p* − MC) / MC'],0,'Market power exists when µ = p*/MC(q*) > 1.'),
Q('q14','c1','practice','Price elasticity and market power are:',['inversely related: |ε| = ∞ means no market power','positively related: |ε| = ∞ means extreme market power','unrelated','equal'],0,'Lerner index (p − MC)/p = 1/|ε|.'),
Q('q15','c1','practice','In the long run, firms under monopolistic competition:',['earn zero economic profit because entry shifts their demand inward and makes it flatter','earn monopoly profits thanks to barriers to entry','are price takers','always exit the market'],0,'Free entry continues until profit is zero.'),
Q('q16','c1','practice','The “desert water shop” and “Stromae’s currency platform” illustrate respectively:',['perfectly inelastic and perfectly elastic demand','perfectly elastic and perfectly inelastic demand','two inelastic demands','two elastic demands'],0,'Indila pays any price; nobody uses a platform with a worse rate than the market rate.'),
Q('q17','c1','practice','According to De Loecker et al. (2020), the rise of markups:',['comes mainly from a small minority of firms setting very high markups','comes from all firms raising markups equally','is limited to U.S. firms','has reversed since 2000'],0,'The distribution changes: a few firms drive the increase, in the US, Europe and Asia.'),
Q('q18','c1','practice','Why can some market power be desirable according to the INSIGHTS?',['It rewards and finances innovation (dynamic efficiency) and consumers value product differentiation','It maximizes static welfare','It raises the labour share of revenue','It always lowers prices'],0,'Static vs dynamic efficiency: patents give a temporary monopoly to stimulate R&D. Excessive market power is welfare destroying.'),
Q('q19','c1','course','Exercise 1.7: copper is best classified as:',['close-to-perfect competition','monopolistic competition','oligopoly','monopoly'],0,'Many producers of a largely homogeneous commodity, price takers.'),
Q('q20','c1','course','Exercise 1.7: mobile phone producers are best classified as:',['oligopoly','monopolistic competition','perfect competition','monopoly'],0,'A few large producers with technological, scale, branding and legal barriers.'),
Q('q21','c1','course','Exercise 1.7: bottled water is best classified as:',['monopolistic competition','perfect competition','oligopoly','monopoly'],0,'Many firms, strong branding and differentiation.'),
Q('q22','c1','course','Mock exam Q1a: iPhones (Apple) are sold under:',['oligopoly','perfect competition','monopolistic competition','monopoly'],0,'Free entry/exit, market atomism and homogeneity are violated; a few large firms: oligopoly.'),
Q('q23','c1','practice','Which is NOT one of the four conditions of perfect competition?',['Product differentiation','Market atomism','Perfect information','Free entry and exit'],0,'The fourth condition is homogeneity, the opposite of differentiation.'),
Q('q24','c2','course','True or false: the cartel (cooperative) solution guarantees maximum profit for at least one of the two duopolists.',TF,1,'FALSE (2.1): it maximizes the (weighted) <b>sum</b> of profits.'),
Q('q25','c2','course','True or false: the profit of each duopolist is higher when fulfilling the agreement than when both break it, because the profit depends only on their own production.',TF,1,'FALSE (2.2): profits depend on the actions of all players.'),
Q('q26','c2','course','True or false: in a game with a unique Nash equilibrium, there is always an expected outcome: this Nash equilibrium.',TF,0,'TRUE (2.3): a unique NE is the expected solution.'),
Q('q27','c2','course','True or false: the joint profit of the duopolists is higher when maintaining the agreement than when both break it.',TF,0,'TRUE (2.A1).'),
Q('q28','c2','course','True or false: Hotelling teaches that in a duopoly, when there is the possibility of price competition, there will be minimal product differentiation.',TF,1,'FALSE (2.A2): price competition leads to <b>more</b> differentiation; minimal differentiation arises under fixed prices.'),
Q('q29','c2','course','True or false: when both firms maintain the cartel agreement, they choose production levels as if they were one merged firm with a monopoly.',TF,0,'TRUE (2.A3).'),
Q('q30','c2','course','True or false: in a game with a unique Nash equilibrium, there is always an equilibrium in dominant strategies.',TF,1,'FALSE (2.A4): a NE need not consist of dominant strategies (e.g. the mock exam Q2: unique NE, but Duopolist 1 has no dominant strategy).'),
Q('q31','c2','course','Two factories: reducing pollution costs €5m each; if one reduces and the other not, the reducer gets a €10m subsidy and the other a €8m penalty; if both reduce, each gets €5m; if neither, each gets a €4m penalty. Which is correct?',['Factory A and B will both reduce their emissions','Neither will reduce','Only A reduces','Only B reduces'],0,'2.A9 (d): payoffs (0, 0), (5, −8), (−8, 5), (−4, −4): reducing is dominant for both.'),
Q('q32','c2','course','1. In an oligopoly, firms only need their own cost structure and demand curve to set output. 2. Game theory analyzes decisions that take other players’ reactions into account.',['1 is FALSE, 2 is TRUE','1 and 2 are TRUE','1 is TRUE, 2 is FALSE','1 and 2 are FALSE'],0,'2.A10 (c).'),
Q('q33','c2','course','1. In the prisoner’s dilemma, both confess, which gives the lowest total prison time. 2. Game theory always guarantees the best outcome for each individual player.',['1 and 2 are FALSE','1 and 2 are TRUE','1 is TRUE, 2 is FALSE','1 is FALSE, 2 is TRUE'],0,'2.A11 (d): (confess, confess) gives 8 + 8 years, far more than (deny, deny); self-interest need not give the best outcome.'),
Q('q34','c2','course','1. Nash equilibrium is a more general concept than equilibrium in dominant strategies and can be multiple. 2. A Nash equilibrium is always unique.',['1 is TRUE, 2 is FALSE','1 and 2 are TRUE','1 is FALSE, 2 is TRUE','1 and 2 are FALSE'],0,'2.A12 (b).'),
Q('q35','c2','course','Hotelling: 1. A heterogeneous duopoly tends towards a homogeneous duopoly in the absence of price competition. 2. More severe price competition implies more product differentiation.',['1 and 2 are TRUE','1 is TRUE, 2 is FALSE','1 is FALSE, 2 is TRUE','1 and 2 are FALSE'],0,'2.A13 (a).'),
Q('q36','c2','course','Hotelling: 1. Under fixed prices, both vendors end up at the centre of the beach. 2. The equilibrium under fixed prices differs from the equilibrium under liberalized prices.',['1 and 2 are TRUE','1 is TRUE, 2 is FALSE','1 is FALSE, 2 is TRUE','1 and 2 are FALSE'],0,'2.A14 (a).'),
Q('q37','c2','course','Mock exam Q1c: “When duopolists do not engage in price competition, we expect the duopoly to be homogeneous.” The right explanation is:',['Hotelling under fixed prices: both carts move to the centre, the unique Nash equilibrium','The paradox of Bertrand: a price war drives price to marginal cost','Repeated games and tit-for-tat','First-degree price discrimination'],0,'The mock’s note to students: answering with Bertrand is incorrect.'),
Q('q38','c2','practice','In the 4 × 4 output game (Table 4 of the INSIGHTS), how many Nash equilibria are there?',['3','1','2','4'],0,'(s3, t2), (s2, t3) and (s3, t3).'),
Q('q39','c2','practice','In the battle of the sexes, there are:',['no dominant strategies and two Nash equilibria','dominant strategies for both players','a unique Nash equilibrium','no Nash equilibrium'],0,'Both (football, football) and (cinema, cinema) are NE: coordination matters.'),
Q('q40','c2','practice','The paradox of Bertrand states that a homogeneous duopoly with price competition leads to:',['the perfect-competition outcome: price = marginal cost, zero profit','the monopoly outcome','minimal product differentiation','a cartel'],0,'A price war: each undercuts the other until p = min AC = MC.'),
Q('q41','c2','practice','In Hotelling’s model with fixed prices, the location at 500 m from each end of the 2 km beach is:',['socially optimal (average walk 250 m) but not the expected solution','the unique Nash equilibrium','the outcome of a price war','maximal product differentiation chosen by the vendors'],0,'Each vendor moves to the centre to steal customers; the centre (average walk 0.5 km) is the NE.'),
Q('q42','c2','practice','With liberalized prices, is “both carts at the centre” still a Nash equilibrium?',['No: Bertrand gives zero profit there, so each cart gains by moving away (differentiation)','Yes, it is still the unique NE','Yes, but only in the long run','No, because prices must stay fixed'],0,'Solution 2.A15: differentiation lets them price above MC.'),
Q('q43','c2','practice','In an indefinitely repeated maintain–break game, tit-for-tat means:',['start by maintaining, then copy what the rival did in the previous period','always break','always maintain','break in the last period only'],0,'Retaliation can make cooperation sustainable when future profits matter enough.'),
Q('q44','c2','practice','If firms know with certainty the final period of a repeated game:',['both break in the last period and cooperation unravels backwards','tit-for-tat sustains cooperation in every period','they always maintain','the game has no Nash equilibrium'],0,'No retaliation is possible after the final period.'),
Q('q45','c2','practice','In the six-stage centipede game, backward induction predicts:',['Player A stops immediately: (2; 0)','both continue to the end: (8; 6)','Player B stops at the last node: (5; 7)','Player A stops at the fifth node: (6; 4)'],0,'At each node the mover stops, anticipating that the other would stop next.'),
Q('q46','c2','practice','In the ultimatum game with 10 units and purely self-interested players, backward induction predicts:',['(9; 1)','(5; 5)','(10; 0)','(0; 10)'],0,'B accepts any positive offer, so A offers 1. In experiments offers are higher: fairness matters.'),
Q('q47','c2','practice','A threat in a sequential game is credible when:',['carrying it out is optimal for the player when the decision node is reached','it is announced publicly','it hurts the rival','it is made by the first mover'],0,'Amazon’s imitation threat is credible (8 > 3); Booking’s commission cut is not (3 < 4).'),
Q('q48','c2','practice','Case Uber vs Lyft: does the high subsidy deter Lyft, and is it optimal for Uber?',['It deters Lyft, but it is too costly: Uber prefers the low subsidy (5 > 2)','It deters Lyft and is optimal','It does not deter Lyft','Lyft never enters'],0,'Successful deterrence is not automatically profitable.'),
Q('q49','c2','practice','“If you can’t win the game, change the rules” refers to:',['mechanism design: changing payoffs (e.g. CO₂ taxes) so the desired outcome becomes an equilibrium','tit-for-tat','the paradox of Bertrand','backward induction'],0,'E.g. lowering the payoff of unilateral defection from 10 to 3 turns scenario 2 into scenario 1.'),
Q('q50','c2','practice','In the CO₂ game with two Nash equilibria (scenario 1), which avenue does NOT help reach (Reduce, Reduce) according to the INSIGHTS?',['Playing the game simultaneously and only once without any agreement','Making the game sequential (a first mover such as the EU)','Bilateral or multilateral cooperation','Social norms'],0,'Sequential choice, cooperation and social norms are the three avenues.'),
Q('q51','c2','course','Solution 2.4 (Aimée and Étienne): the expected solution is:',['(Confess; Confess)','(Deny; Deny)','(Confess; Deny)','No expected solution'],0,'Confessing is dominant for both (−5 > −6 and −1 > −2).'),
Q('q52','c3','course','True or false: under constant returns to scale, long-run average costs are constant and everywhere equal to long-run marginal costs.',TF,0,'TRUE: LAC = LMC constant.'),
Q('q53','c3','course','True or false: in the short run, a profit-maximizing firm continues to produce if its average revenue is below average cost but total revenue exceeds variable cost.',TF,0,'TRUE: p ≥ AVC (TR ≥ VC) is the short-run condition; fixed cost is paid anyway.'),
Q('q54','c3','course','True or false: the total cost function always starts from the origin.',TF,1,'FALSE (3.A2): with a fixed cost, TC(0) = FC > 0 in the short run.'),
Q('q55','c3','course','True or false: in the long run, buildings are the only fixed input.',TF,1,'FALSE (3.A3): in the long run all inputs are variable.'),
Q('q56','c3','practice','For the inverse demand p = a − bq, marginal revenue is:',['MR = a − 2bq','MR = a − bq','MR = a − bq/2','MR = 2a − bq'],0,'Same intercept, twice the slope.'),
Q('q57','c3','practice','Total revenue is maximal where:',['MR = 0','MR = MC','p = MC','AC is minimal'],0,'For q = 2400 − 80p, TR is maximal at q = 1 200.'),
Q('q58','c3','practice','With positive marginal cost, the profit-maximizing quantity of a monopolist is:',['smaller than the revenue-maximizing quantity','larger than the revenue-maximizing quantity','equal to it','always the scale-efficient quantity'],0,'MR(q*) = MC > 0, so q* is left of MR = 0.'),
Q('q59','c3','practice','Marginal cost crosses average cost:',['at the minimum of average cost','at the maximum of average cost','where MR = 0','never'],0,'If MC < AC, AC falls; if MC > AC, AC rises.'),
Q('q60','c3','practice','In the short run, a firm temporarily shuts down when:',['p(q*) < AVC(q*)','p(q*) < AC(q*)','p(q*) < MC(q*)','TR < TC'],0,'Fixed cost is paid in both cases, so only variable cost matters.'),
Q('q61','c3','practice','Under market segmentation, which segment gets the higher price?',['The less price-elastic segment','The more price-elastic segment','The larger segment','Both pay the same'],0,'Mock Q1b: sell more at a lower price in the more elastic segment.'),
Q('q62','c3','practice','An essential condition for market segmentation is that:',['buyers in different segments cannot (easily) resell to each other','all buyers have the same elasticity','marginal cost differs by segment','the firm is a price taker'],0,'Otherwise the low-price group resells to the high-price group.'),
Q('q63','c3','practice','Under first-degree price discrimination:',['consumer surplus is zero and output equals the perfect-competition quantity','the price is uniform','output is lower than under uniform pricing','consumer surplus is maximal'],0,'Each buyer pays his WTP; the firm sells while WTP ≥ MC.'),
Q('q64','c3','practice','In the long-run equilibrium of monopolistic competition:',['the demand curve is tangent to AC, profit is zero and p > MC','p = MC = min AC','profit is positive','the firm produces at the scale-efficient quantity'],0,'Market power remains; AC is still falling, so q < qSE.'),
Q('q65','c3','practice','A fixed cost:',['affects whether the firm produces in the long run, but not the quantity where MR = MC','changes marginal cost','is zero in the short run','is part of marginal revenue'],0,'MC = dTC/dq = dVC/dq.'),
Q('q66','c3','practice','Economic profit differs from accounting profit because it:',['also deducts implicit opportunity costs','ignores fixed costs','includes only cash costs','is always larger'],0,'Zero economic profit can mean a normal accounting return.'),
Q('q67','c3','practice','Under increasing returns to scale:',['LAC decreases and LMC < LAC','LAC increases and LMC > LAC','LAC = LMC constant','short-run costs are fixed'],0,'Output rises more than proportionally with inputs.'),
Q('q68','c4','practice','For a price-taking firm:',['p = AR = MR','MR < p','AR > MR','MR = 0'],0,'Every unit sells at the same market price.'),
Q('q69','c4','practice','The supply curve of a perfectly competitive firm (all costs avoidable) is:',['the increasing part of MC at and above the minimum of AC','the AC curve','the demand curve','the MR curve'],0,'Below min AC the firm supplies zero; with unavoidable FC in the short run, the threshold is min AVC.'),
Q('q70','c4','practice','An initial market clears at p0 and firms earn positive profit. With free entry:',['firms enter, market supply shifts right and the price falls','firms exit and the price rises','nothing changes because the market clears','the price rises to attract more buyers'],0,'Clearing does not imply a stable number of firms.'),
Q('q71','c4','practice','In market equilibrium with free entry and exit (identical firms):',['p* = MC(q*) = AC(q*), so q* = qSE and p* = min AC','p* > AC(q*)','p* = MR > MC','profit is maximal and positive'],0,'Profit maximization plus zero profit.'),
Q('q72','c4','practice','No Grain, No Gain: moving from the initial situation (p0 = 10, 4 firms) to equilibrium (p* = 8, 6 firms):',['price and output per firm fall; number of firms and total output rise','all variables rise','total output falls','profit per firm rises'],0,'Q: 20 → 24, q: 5 → 4, n: 4 → 6, Π: 9 → 0.'),
Q('q73','c4','practice','A natural monopoly arises when:',['the scale-efficient output is large relative to market demand at the minimum average cost','there are many small firms','average cost rises from the first unit','the government grants a licence'],0,'Two scale-efficient firms would supply more than demand; a second firm’s residual demand has AC > p.'),
Q('q74','c4','practice','In the INSIGHTS graph example (min LAC 15 at qSE = 1 000, demand 1 200 at p = 15), a second firm:',['would serve only 200 units at an average cost above 15 and cannot break even','would earn positive profit','would share the market equally','would set p = 15 and earn zero profit'],0,'Entry is possible but not profitable.'),
Q('q75','c4','practice','A cost shock (higher energy or transport costs) in a competitive market:',['shifts market supply left: higher price, lower quantity, possible exit','shifts demand left','lowers the price','has no effect on price takers'],0,'MC and AC shift up for every firm.'),
Q('q76','c4','practice','Why is perfect competition “statically efficient”?',['Price equals marginal cost: there is no markup from market power','Firms innovate the most','Profit is maximal','Prices never change'],0,'Dynamic efficiency (innovation) can require some market power: the policy goal is effective competition.'),
Q('q77','c4','practice','Zero economic profit in market equilibrium means that:',['revenue covers all explicit and implicit costs, including a normal return for the entrepreneur','the entrepreneur earns nothing','firms are making losses','the market does not clear'],0,'Economic cost includes opportunity costs.')];

/* ---------- exercises ---------- */
const gameSolve=m=>{ // m[i][j] = [row payoff, col payoff]
  const R=m.length,C=m[0].length,bestRow=j=>Math.max(...m.map(r=>r[j][0])),bestCol=i=>Math.max(...m[i].map(c=>c[1]));
  const ne=[];for(let i=0;i<R;i++)for(let j=0;j<C;j++)if(m[i][j][0]===bestRow(j)&&m[i][j][1]===bestCol(i))ne.push([i,j]);
  let dr=null;for(let i=0;i<R;i++)if([...Array(C).keys()].every(j=>m.every((r,k)=>k===i||m[i][j][0]>r[j][0])))dr=i;
  let dc=null;for(let j=0;j<C;j++)if([...Array(R).keys()].every(i=>m[i].every((c,k)=>k===j||m[i][j][1]>c[1])))dc=j;
  return {ne,dr,dc}};
const mtx=(m,rl='Duopolist 1',cl='Duopolist 2',rs=['S1','S2','S3','S4'],cs=['T1','T2','T3','T4'])=>Rev.W.pmTable(m,rs.slice(0,m.length),cs.slice(0,m[0].length),rl,cl);

